package httpapi

import (
	"bytes"
	"encoding/json"
	"errors"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/google/uuid"

	"wordweave/internal/admin"
	"wordweave/internal/ai"
	"wordweave/internal/learning"
)

type adminCredentialDTO struct {
	Configured bool    `json:"configured"`
	MaskedHint *string `json:"masked_hint"`
	UpdatedAt  *string `json:"updated_at"`
}

type adminModelDTO struct {
	ID                 string   `json:"id"`
	DisplayName        string   `json:"display_name"`
	Description        *string  `json:"description"`
	OpenRouterModelID  string   `json:"openrouter_model_id"`
	Enabled            bool     `json:"enabled"`
	AssignedGroupCodes []string `json:"assigned_group_codes"`
	CreatedAt          string   `json:"created_at"`
	UpdatedAt          string   `json:"updated_at"`
}

type adminGroupModelDTO struct {
	ID          string `json:"id"`
	DisplayName string `json:"display_name"`
	Enabled     bool   `json:"enabled"`
}

type adminGroupDTO struct {
	Code            string               `json:"code"`
	Rolling24hLimit *int                 `json:"rolling_24h_limit"`
	MaxEntries      int                  `json:"max_entries"`
	AllowedLengths  []string             `json:"allowed_lengths"`
	Models          []adminGroupModelDTO `json:"models"`
}

type adminUserSummaryDTO struct {
	ID        string  `json:"id"`
	Username  string  `json:"username"`
	Role      string  `json:"role"`
	PlanCode  *string `json:"plan_code"`
	Status    string  `json:"status"`
	CreatedAt string  `json:"created_at"`
}

type adminUserDetailDTO struct {
	ID                 string                   `json:"id"`
	Username           string                   `json:"username"`
	Role               string                   `json:"role"`
	PlanCode           *string                  `json:"plan_code"`
	Status             string                   `json:"status"`
	UILocale           *string                  `json:"ui_locale"`
	CreatedAt          string                   `json:"created_at"`
	LearningBatchCount int                      `json:"learning_batch_count"`
	GenerationQuota    *adminGenerationQuotaDTO `json:"generation_quota"`
}

type adminGenerationQuotaDTO struct {
	Kind      string `json:"kind"`
	Remaining *int   `json:"remaining"`
}

func mapAdminCredential(status ai.CredentialStatus) adminCredentialDTO {
	return adminCredentialDTO{Configured: status.Configured, MaskedHint: status.MaskedHint, UpdatedAt: status.UpdatedAt}
}

func mapAdminModel(model admin.Model) adminModelDTO {
	groups := model.AssignedGroupCodes
	if groups == nil {
		groups = []string{}
	}
	return adminModelDTO{
		ID: model.ID.String(), DisplayName: model.DisplayName, Description: model.Description,
		OpenRouterModelID: model.OpenRouterModelID, Enabled: model.Enabled, AssignedGroupCodes: groups,
		CreatedAt: model.CreatedAt.Format(time.RFC3339Nano), UpdatedAt: model.UpdatedAt.Format(time.RFC3339Nano),
	}
}

func mapAdminGroup(group admin.Group) adminGroupDTO {
	lengths := group.AllowedLengths
	if lengths == nil {
		lengths = []string{}
	}
	dto := adminGroupDTO{Code: group.Code, Rolling24hLimit: group.Rolling24hLimit, MaxEntries: group.MaxEntries, AllowedLengths: lengths, Models: make([]adminGroupModelDTO, 0, len(group.Models))}
	for _, model := range group.Models {
		dto.Models = append(dto.Models, adminGroupModelDTO{ID: model.ID.String(), DisplayName: model.DisplayName, Enabled: model.Enabled})
	}
	return dto
}

func mapAdminUserSummary(user admin.User) adminUserSummaryDTO {
	return adminUserSummaryDTO{ID: user.ID.String(), Username: user.Username, Role: user.Role, PlanCode: user.PlanCode, Status: user.Status, CreatedAt: user.CreatedAt.Format(time.RFC3339Nano)}
}

func mapAdminUserDetail(user admin.User) adminUserDetailDTO {
	var quota *adminGenerationQuotaDTO
	if user.GenerationQuota != nil {
		quota = &adminGenerationQuotaDTO{Kind: user.GenerationQuota.Kind, Remaining: user.GenerationQuota.Remaining}
	}
	return adminUserDetailDTO{
		ID: user.ID.String(), Username: user.Username, Role: user.Role,
		PlanCode: user.PlanCode, Status: user.Status, UILocale: user.UILocale,
		CreatedAt:          user.CreatedAt.Format(time.RFC3339Nano),
		LearningBatchCount: user.LearningBatchCount, GenerationQuota: quota,
	}
}

func (server *Server) adminCredential(writer http.ResponseWriter, request *http.Request) {
	status, err := server.admin.CredentialStatus(request.Context())
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusOK, mapAdminCredential(status))
}

func (server *Server) adminPutCredential(writer http.ResponseWriter, request *http.Request) {
	var body struct {
		APIKey    string `json:"api_key"`
		Confirmed bool   `json:"confirmed"`
	}
	if !decodeOrProblem(writer, request, &body, 16<<10) {
		return
	}
	actor, _ := actorFromContext(request.Context())
	status, err := server.admin.PutCredential(request.Context(), actor, body.APIKey, body.Confirmed)
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusOK, mapAdminCredential(status))
}

func queryLimit(request *http.Request) (int, error) {
	if raw := request.URL.Query().Get("limit"); raw != "" {
		limit, err := strconv.Atoi(raw)
		if err != nil {
			return 0, admin.ErrValidation
		}
		return limit, nil
	}
	return 20, nil
}

func (server *Server) adminListModels(writer http.ResponseWriter, request *http.Request) {
	limit, err := queryLimit(request)
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	var cursor *admin.ModelCursor
	if raw := request.URL.Query().Get("cursor"); raw != "" {
		var decoded admin.ModelCursor
		if err := server.cursor.Decode("admin-models", raw, &decoded); err != nil {
			server.writeAdminProblem(writer, request, admin.ErrValidation)
			return
		}
		cursor = &decoded
	}
	items, hasMore, err := server.admin.ListModels(request.Context(), cursor, limit)
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	dtos := make([]adminModelDTO, 0, len(items))
	for _, item := range items {
		dtos = append(dtos, mapAdminModel(item))
	}
	var next *string
	if hasMore && len(items) > 0 {
		last := items[len(items)-1]
		value, err := server.cursor.Encode("admin-models", admin.ModelCursor{CreatedAt: last.CreatedAt, ID: last.ID})
		if err != nil {
			server.writeAdminProblem(writer, request, err)
			return
		}
		next = &value
	}
	writeListJSON(writer, request, struct {
		Items []adminModelDTO `json:"items"`
	}{Items: dtos}, next, hasMore)
}

func (server *Server) adminCreateModel(writer http.ResponseWriter, request *http.Request) {
	var body struct {
		DisplayName       string  `json:"display_name"`
		Description       *string `json:"description"`
		OpenRouterModelID string  `json:"openrouter_model_id"`
	}
	if !decodeOrProblem(writer, request, &body, 16<<10) {
		return
	}
	model, err := server.admin.CreateModel(request.Context(), body.DisplayName, body.Description, body.OpenRouterModelID)
	server.writeAdminModelResult(writer, request, model, err, http.StatusCreated)
}

type optionalString struct {
	Set   bool
	Value *string
}

type requiredNullableInt struct {
	Set   bool
	Value *int
}

func (value *requiredNullableInt) UnmarshalJSON(raw []byte) error {
	value.Set = true
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		value.Value = nil
		return nil
	}
	var decoded int
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return err
	}
	value.Value = &decoded
	return nil
}

type requiredStrings struct {
	Set    bool
	Values []string
}

func (value *requiredStrings) UnmarshalJSON(raw []byte) error {
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return errors.New("array cannot be null")
	}
	if err := json.Unmarshal(raw, &value.Values); err != nil {
		return err
	}
	value.Set = true
	return nil
}

type requiredUUIDs struct {
	Set    bool
	Values []uuid.UUID
}

func (value *requiredUUIDs) UnmarshalJSON(raw []byte) error {
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return errors.New("array cannot be null")
	}
	if err := json.Unmarshal(raw, &value.Values); err != nil {
		return err
	}
	value.Set = true
	return nil
}

func (value *optionalString) UnmarshalJSON(raw []byte) error {
	value.Set = true
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		value.Value = nil
		return nil
	}
	var decoded string
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return err
	}
	value.Value = &decoded
	return nil
}

func (server *Server) adminPatchModel(writer http.ResponseWriter, request *http.Request) {
	modelID, ok := parseAdminUUID(writer, request, "model_id")
	if !ok {
		return
	}
	var body struct {
		DisplayName       optionalString `json:"display_name"`
		Description       optionalString `json:"description"`
		OpenRouterModelID optionalString `json:"openrouter_model_id"`
	}
	if !decodeOrProblem(writer, request, &body, 16<<10) {
		return
	}
	patch := admin.ModelPatch{DescriptionSet: body.Description.Set, Description: body.Description.Value}
	if body.DisplayName.Set {
		if body.DisplayName.Value == nil {
			server.writeAdminProblem(writer, request, admin.ErrValidation)
			return
		}
		patch.DisplayNameSet, patch.DisplayName = true, *body.DisplayName.Value
	}
	if body.OpenRouterModelID.Set {
		if body.OpenRouterModelID.Value == nil {
			server.writeAdminProblem(writer, request, admin.ErrValidation)
			return
		}
		patch.OpenRouterModelIDSet, patch.OpenRouterModelID = true, *body.OpenRouterModelID.Value
	}
	model, err := server.admin.PatchModel(request.Context(), modelID, patch)
	server.writeAdminModelResult(writer, request, model, err, http.StatusOK)
}

func (server *Server) adminEnableModel(writer http.ResponseWriter, request *http.Request) {
	server.adminSetModelEnabled(writer, request, true)
}

func (server *Server) adminDisableModel(writer http.ResponseWriter, request *http.Request) {
	server.adminSetModelEnabled(writer, request, false)
}

func (server *Server) adminSetModelEnabled(writer http.ResponseWriter, request *http.Request, enabled bool) {
	var body struct{}
	if !decodeOrProblem(writer, request, &body, 128) {
		return
	}
	modelID, ok := parseAdminUUID(writer, request, "model_id")
	if !ok {
		return
	}
	if enabled {
		// Enabling performs a real structured stream compatibility check. Like a
		// learner generation, it is governed by the request context and provider
		// terminal event rather than the ordinary JSON response write timeout.
		_ = http.NewResponseController(writer).SetWriteDeadline(time.Time{})
	}
	model, err := server.admin.SetModelEnabled(request.Context(), modelID, enabled)
	server.writeAdminModelResult(writer, request, model, err, http.StatusOK)
}

func (server *Server) writeAdminModelResult(writer http.ResponseWriter, request *http.Request, model admin.Model, err error, status int) {
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, status, struct {
		Model adminModelDTO `json:"model"`
	}{Model: mapAdminModel(model)})
}

func (server *Server) adminListGroups(writer http.ResponseWriter, request *http.Request) {
	items, err := server.admin.ListGroups(request.Context())
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	dtos := make([]adminGroupDTO, 0, len(items))
	for _, item := range items {
		dtos = append(dtos, mapAdminGroup(item))
	}
	writeJSON(writer, request, http.StatusOK, struct {
		Items []adminGroupDTO `json:"items"`
	}{Items: dtos})
}

func (server *Server) adminPutGroup(writer http.ResponseWriter, request *http.Request) {
	var body struct {
		Rolling24hLimit requiredNullableInt `json:"rolling_24h_limit"`
		MaxEntries      int                 `json:"max_entries"`
		AllowedLengths  requiredStrings     `json:"allowed_lengths"`
		ModelIDs        requiredUUIDs       `json:"model_ids"`
	}
	if !decodeOrProblem(writer, request, &body, 64<<10) {
		return
	}
	if !body.Rolling24hLimit.Set || !body.AllowedLengths.Set || !body.ModelIDs.Set {
		server.writeAdminProblem(writer, request, admin.ErrValidation)
		return
	}
	group, err := server.admin.PutGroup(request.Context(), chi.URLParam(request, "group_code"), body.Rolling24hLimit.Value, body.MaxEntries, body.AllowedLengths.Values, body.ModelIDs.Values)
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusOK, struct {
		Group adminGroupDTO `json:"group"`
	}{Group: mapAdminGroup(group)})
}

func (server *Server) adminListUsers(writer http.ResponseWriter, request *http.Request) {
	limit, err := queryLimit(request)
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	query := strings.TrimSpace(request.URL.Query().Get("username"))
	normalizedQuery := admin.NormalizeUserQuery(query)
	actor, ok := actorFromContext(request.Context())
	if !ok || !actor.IsAdmin() {
		writeProblem(writer, request, http.StatusForbidden, "forbidden", "Access denied", "Administrator access is required.")
		return
	}
	scope := adminUserCursorScope(actor.ID, normalizedQuery)
	var cursor *admin.UserCursorV2
	if raw := request.URL.Query().Get("cursor"); raw != "" {
		var decoded admin.UserCursorV2
		if err := server.cursor.Decode(scope, raw, &decoded); err != nil || !admin.ValidUserCursor(normalizedQuery, decoded) {
			server.writeAdminProblem(writer, request, admin.ErrInvalidCursor)
			return
		}
		cursor = &decoded
	}
	items, hasMore, err := server.admin.ListUsers(request.Context(), normalizedQuery, cursor, limit)
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	dtos := make([]adminUserSummaryDTO, 0, len(items))
	for _, item := range items {
		dtos = append(dtos, mapAdminUserSummary(item))
	}
	var next *string
	if hasMore && len(items) > 0 {
		last := items[len(items)-1]
		value, err := server.cursor.Encode(scope, admin.NewUserCursor(normalizedQuery, last))
		if err != nil {
			server.writeAdminProblem(writer, request, err)
			return
		}
		next = &value
	}
	writeListJSON(writer, request, struct {
		Items []adminUserSummaryDTO `json:"items"`
	}{Items: dtos}, next, hasMore)
}

func adminUserCursorScope(adminID uuid.UUID, normalizedQuery string) string {
	return "api-103:admin-users:v2:" + adminID.String() + ":" + normalizedQuery
}

func (server *Server) adminGetUser(writer http.ResponseWriter, request *http.Request) {
	userID, ok := parseAdminUUID(writer, request, "user_id")
	if !ok {
		return
	}
	user, err := server.admin.GetUser(request.Context(), userID)
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusOK, struct {
		User adminUserDetailDTO `json:"user"`
	}{User: mapAdminUserDetail(user)})
}

func (server *Server) adminChangeUserGroup(writer http.ResponseWriter, request *http.Request) {
	userID, ok := parseAdminUUID(writer, request, "user_id")
	if !ok {
		return
	}
	var body struct {
		GroupCode string `json:"group_code"`
		Confirmed bool   `json:"confirmed"`
	}
	if !decodeOrProblem(writer, request, &body, 1024) {
		return
	}
	user, err := server.admin.ChangeUserGroup(request.Context(), userID, body.GroupCode, body.Confirmed)
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusOK, struct {
		User       adminUserDetailDTO `json:"user"`
		QuotaReset bool               `json:"quota_reset"`
	}{User: mapAdminUserDetail(user), QuotaReset: true})
}

func (server *Server) adminResetUserPassword(writer http.ResponseWriter, request *http.Request) {
	userID, ok := parseAdminUUID(writer, request, "user_id")
	if !ok {
		return
	}
	var body struct {
		NewPassword             string `json:"new_password"`
		NewPasswordConfirmation string `json:"new_password_confirmation"`
		Confirmed               bool   `json:"confirmed"`
	}
	if !decodeOrProblem(writer, request, &body, 16<<10) {
		return
	}
	if !server.requireAuthRate(writer, request, "admin-reset-password", userID.String(), 10, 6*time.Second) {
		return
	}
	if err := server.admin.ResetUserPassword(request.Context(), userID, body.NewPassword, body.NewPasswordConfirmation, body.Confirmed); err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	writeNoContent(writer)
}

func (server *Server) adminListUserBatches(writer http.ResponseWriter, request *http.Request) {
	userID, ok := parseAdminUUID(writer, request, "user_id")
	if !ok {
		return
	}
	if err := server.admin.RequireUser(request.Context(), userID); err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	limit, err := queryLimit(request)
	if err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	scope := "admin-user-batches:" + userID.String()
	var cursor *learning.BatchCursor
	if raw := request.URL.Query().Get("cursor"); raw != "" {
		var decoded learning.BatchCursor
		if err := server.cursor.Decode(scope, raw, &decoded); err != nil {
			server.writeAdminProblem(writer, request, admin.ErrValidation)
			return
		}
		cursor = &decoded
	}
	items, hasMore, err := server.admin.Learning().ListBatches(request.Context(), userID, nil, cursor, limit)
	if err != nil {
		server.writeLearningProblem(writer, request, err)
		return
	}
	dtos := make([]batchSummaryDTO, 0, len(items))
	for _, item := range items {
		dtos = append(dtos, mapBatchSummary(item))
	}
	var next *string
	if hasMore && len(items) > 0 {
		last := items[len(items)-1]
		value, err := server.cursor.Encode(scope, learning.BatchCursor{SavedAt: last.SavedAt, ID: last.ID})
		if err != nil {
			server.writeAdminProblem(writer, request, err)
			return
		}
		next = &value
	}
	writeListJSON(writer, request, struct {
		Items []batchSummaryDTO `json:"items"`
	}{Items: dtos}, next, hasMore)
}

func (server *Server) adminGetUserBatch(writer http.ResponseWriter, request *http.Request) {
	userID, ok := parseAdminUUID(writer, request, "user_id")
	if !ok {
		return
	}
	batchID, ok := parseAdminUUID(writer, request, "batch_id")
	if !ok {
		return
	}
	if err := server.admin.RequireUser(request.Context(), userID); err != nil {
		server.writeAdminProblem(writer, request, err)
		return
	}
	detail, err := server.admin.Learning().BatchDetail(request.Context(), userID, batchID)
	if err != nil {
		server.writeLearningProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusOK, struct {
		Batch batchDetailDTO `json:"batch"`
	}{Batch: mapBatchDetail(detail)})
}

func parseAdminUUID(writer http.ResponseWriter, request *http.Request, parameter string) (uuid.UUID, bool) {
	id, err := uuid.Parse(chi.URLParam(request, parameter))
	if err != nil {
		writeProblem(writer, request, http.StatusNotFound, "not_found", "Not found", "The requested resource could not be found.")
		return uuid.Nil, false
	}
	return id, true
}

func (server *Server) writeAdminProblem(writer http.ResponseWriter, request *http.Request, err error) {
	var providerError *ai.ProviderError
	switch {
	case errors.Is(err, admin.ErrNotFound):
		writeProblem(writer, request, http.StatusNotFound, "not_found", "Not found", "The requested resource could not be found.")
	case errors.Is(err, admin.ErrInvalidCursor):
		writeProblem(writer, request, http.StatusUnprocessableEntity, "validation_failed", "Request could not be accepted", "One or more fields need attention.", fieldError{Field: "cursor", Code: "invalid"})
	case errors.Is(err, admin.ErrConflict):
		writeProblem(writer, request, http.StatusConflict, "conflict", "Resource conflict", "A resource with these values already exists.")
	case errors.Is(err, admin.ErrModelIncompatible):
		writeProblem(writer, request, http.StatusUnprocessableEntity, "model_incompatible", "Model is not compatible", "The model could not complete the required structured streaming check.")
	case errors.Is(err, admin.ErrValidation):
		writeProblem(writer, request, http.StatusUnprocessableEntity, "validation_failed", "Request could not be accepted", "One or more fields need attention.")
	case errors.Is(err, ai.ErrCredentialMissing):
		writeProblem(writer, request, http.StatusUnprocessableEntity, "model_incompatible", "Model is not compatible", "OpenRouter is not configured.")
	case errors.As(err, &providerError):
		status := http.StatusBadGateway
		if providerError.Category == ai.FailureAuthentication || providerError.Category == ai.FailureAuthorization {
			status = http.StatusUnprocessableEntity
		}
		writeProblem(writer, request, status, "provider_unavailable", "Provider unavailable", "OpenRouter could not validate this configuration.")
	default:
		writeProblem(writer, request, http.StatusInternalServerError, "internal_error", "Internal error", "The request could not be completed.")
	}
}

//go:build integration

package httpapi

import (
	"context"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"wordweave/internal/platform/postgres"
	"wordweave/internal/platform/security"
)

func TestAdminQuotaHTTPV14(t *testing.T) {
	raw := os.Getenv("TEST_DATABASE_URL")
	if raw == "" {
		t.Skip("TEST_DATABASE_URL is not set")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()
	databaseURL, cleanup := createTestDatabase(t, ctx, raw)
	defer cleanup()
	pool, err := postgres.Open(ctx, databaseURL, "wordweave-quota-http-owner", 4)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Close()
	if err := postgres.Migrate(ctx, pool); err != nil {
		t.Fatal(err)
	}
	const password = "quota-http-test-password"
	hash, err := security.HashPassword(password)
	if err != nil {
		t.Fatal(err)
	}
	adminID := insertSearchAccount(t, ctx, pool, "quota_admin", hash, "admin")
	id := insertSearchAccount(t, ctx, pool, "quota_reader", hash, "learner")
	other := insertSearchAccount(t, ctx, pool, "quota_other", hash, "learner")
	quotaHTTPExec(t, ctx, pool, "UPDATE wordweave.entitlement_groups SET rolling_quota_limit=CASE code WHEN 'registered' THEN 5 WHEN 'pro' THEN 7 ELSE NULL END")
	quotaHTTPExec(t, ctx, pool, "UPDATE wordweave.accounts SET quota_reset_at='2026-01-01T00:00:00Z' WHERE id=$1", id)
	var runID uuid.UUID
	if err := pool.QueryRow(ctx, `WITH model AS (
		INSERT INTO wordweave.ai_models(display_name,provider_model_id,enabled) VALUES ('Quota fixture','test/quota',false) RETURNING id
	), runs AS (
		INSERT INTO wordweave.generation_runs(account_id,credited_account_id,group_code_snapshot,model_id,model_display_name_snapshot,
		provider_model_id_snapshot,meaning_language,scenario,length_code,minimum_words_snapshot,max_entries_snapshot,call_status,disposition,
		quota_charged,counts_toward_cumulative,started_at,completed_at)
		SELECT $1,$1,'registered',model.id,'Quota fixture','test/quota','en','story','short',30,5,'valid','saved',
		true,true,statement_timestamp()-interval '1 hour',statement_timestamp() FROM model CROSS JOIN generate_series(1,3)
		RETURNING id) SELECT id FROM runs LIMIT 1`, id).Scan(&runID); err != nil {
		t.Fatal(err)
	}

	// Run HTTP through the real least-privileged application role. The AI
	// pool is closed: any accidental dependency on credentials/options fails.
	appConfig, err := pgxpool.ParseConfig(databaseURL)
	if err != nil {
		t.Fatal(err)
	}
	appConfig.MaxConns = 4
	appConfig.AfterConnect = func(ctx context.Context, conn *pgx.Conn) error {
		_, err := conn.Exec(ctx, "SET ROLE wordweave_app")
		return err
	}
	appPool, err := pgxpool.NewWithConfig(ctx, appConfig)
	if err != nil {
		t.Fatal(err)
	}
	defer appPool.Close()
	unavailableAI, err := postgres.Open(ctx, databaseURL, "wordweave-quota-no-ai", 1)
	if err != nil {
		t.Fatal(err)
	}
	unavailableAI.Close()
	api, err := New(integrationConfig(databaseURL, "http://127.0.0.1:1"), appPool, unavailableAI)
	if err != nil {
		t.Fatal(err)
	}
	api.SetReady(true)
	application := httptest.NewServer(api.Handler())
	defer application.Close()
	adminClient := loginAdminForSearch(t, application.URL, "quota_admin", password)
	learnerClient := loginAdminForSearch(t, application.URL, "quota_reader", password)
	visitorClient := newBrowserClient(t)
	endpoint := application.URL + "/api/v1/admin/users/" + id.String()
	for _, actor := range []struct {
		name   string
		client *http.Client
		status int
		code   string
	}{
		{"visitor", visitorClient, 401, "authentication_required"}, {"learner", learnerClient, 403, "forbidden"},
	} {
		for _, target := range []string{id.String(), uuid.NewString(), "invalid-id"} {
			response := getJSON(t, actor.client, application.URL+"/api/v1/admin/users/"+target)
			requireStatus(t, response, actor.status)
			if response.body["code"] != actor.code || response.body["data"] != nil {
				t.Fatalf("unsafe %s response", actor.name)
			}
		}
	}
	for _, target := range []string{uuid.NewString(), "invalid-id"} {
		requireStatus(t, getJSON(t, adminClient, application.URL+"/api/v1/admin/users/"+target), 404)
	}
	assertQuotaHTTP(t, adminClient, endpoint, "limited", 2)
	assertQuotaHTTP(t, adminClient, application.URL+"/api/v1/admin/users/"+other.String(), "limited", 5)
	assertQuotaHTTP(t, adminClient, application.URL+"/api/v1/admin/users/"+adminID.String(), "", 0)
	// Input-only attempts to override the snapshot cannot affect server data.
	assertQuotaHTTP(t, adminClient, endpoint+"?remaining=999&group_code=plus&used=0", "limited", 2)

	batchID := quotaHTTPBatch(t, ctx, pool, id, runID)
	detail := assertQuotaHTTP(t, adminClient, endpoint, "limited", 2)
	if nestedValue(t, detail.body, "data", "user", "learning_batch_count") != float64(1) {
		t.Fatal("saved batch not counted")
	}
	batchEndpoint := endpoint + "/batches/" + batchID.String()
	material := getJSON(t, adminClient, batchEndpoint)
	requireStatus(t, material, 200)
	if strings.Contains(material.raw, "generation_quota") {
		t.Fatal("quota leaked into material")
	}
	learnerCSRF := bootstrap(t, learnerClient, application.URL)
	deleted := decodeResponse(t, rawJSONRequest(t, learnerClient, http.MethodDelete, application.URL+"/api/v1/me/batches/"+batchID.String(), learnerCSRF, nil, nil))
	requireStatus(t, deleted, 204)
	detail = assertQuotaHTTP(t, adminClient, endpoint, "limited", 2)
	if nestedValue(t, detail.body, "data", "user", "learning_batch_count") != float64(0) {
		t.Fatal("deleted batch remained in count")
	}
	// Recreate a separate readable batch for the no-history-access checks below.
	batchID = quotaHTTPBatch(t, ctx, pool, id, runID)
	batchEndpoint = endpoint + "/batches/" + batchID.String()

	csrf := bootstrap(t, adminClient, application.URL)
	for _, group := range []string{"pro", "plus", "basic"} {
		changed := putJSON(t, adminClient, endpoint+"/group", csrf, map[string]any{"group_code": group, "confirmed": true})
		requireStatus(t, changed, 200)
		if err := validateAdminQuotaEnvelope([]byte(changed.raw), true); err != nil {
			t.Fatal(err)
		}
		if nestedString(t, changed.body, "data", "user", "plan_code") != group {
			t.Fatal("wrong group")
		}
		if group == "plus" {
			assertQuotaHTTP(t, adminClient, endpoint, "unlimited", 0)
		} else {
			want := 5
			if group == "pro" {
				want = 7
			}
			quota := nestedValue(t, changed.body, "data", "user", "generation_quota").(map[string]any)
			if quota["remaining"] != float64(want) {
				t.Fatalf("quota=%v", quota)
			}
		}
	}
	quotaHTTPExec(t, ctx, pool, "UPDATE wordweave.entitlement_groups SET rolling_quota_limit=0 WHERE code='registered'")
	assertQuotaHTTP(t, adminClient, endpoint, "limited", 0)
	zero := putJSON(t, adminClient, endpoint+"/group", csrf, map[string]any{"group_code": "basic", "confirmed": true})
	requireStatus(t, zero, 200)
	if err := validateAdminQuotaEnvelope([]byte(zero.raw), true); err != nil {
		t.Fatal(err)
	}
	if nestedValue(t, zero.body, "data", "user", "generation_quota", "remaining") != float64(0) {
		t.Fatal("zero was not preserved")
	}
	for _, test := range []struct {
		body   map[string]any
		status int
		code   string
	}{
		{map[string]any{"group_code": "visitor", "confirmed": true}, 422, "validation_failed"},
		{map[string]any{"group_code": "pro", "confirmed": false}, 422, "validation_failed"},
		{map[string]any{"group_code": "pro", "confirmed": true, "generation_quota": map[string]any{"kind": "unlimited", "remaining": nil}}, 400, "malformed_request"},
		{map[string]any{"group_code": "pro", "confirmed": true, "quota_reset_at": "2030-01-01"}, 400, "malformed_request"},
	} {
		response := putJSON(t, adminClient, endpoint+"/group", csrf, test.body)
		requireStatus(t, response, test.status)
		if response.body["code"] != test.code {
			t.Fatal("wrong rejection code")
		}
	}
	requireStatus(t, putJSON(t, adminClient, endpoint+"/group", "", map[string]any{"group_code": "pro", "confirmed": true}), 403)
	badOrigin := decodeResponse(t, rawJSONRequest(t, adminClient, http.MethodPut, endpoint+"/group", csrf, map[string]any{"group_code": "pro", "confirmed": true}, map[string]string{"Origin": "https://not-wordweave.invalid"}))
	requireStatus(t, badOrigin, 403)
	requireStatus(t, putJSON(t, adminClient, application.URL+"/api/v1/admin/users/"+adminID.String()+"/group", csrf, map[string]any{"group_code": "pro", "confirmed": true}), 404)

	// Real SELECT privilege failure after UPDATE must return a safe problem
	// and roll back both group and reset time, without harming read-only pages.
	var reset time.Time
	if err := pool.QueryRow(ctx, "SELECT quota_reset_at FROM wordweave.accounts WHERE id=$1", id).Scan(&reset); err != nil {
		t.Fatal(err)
	}
	quotaHTTPExec(t, ctx, pool, "REVOKE SELECT ON wordweave.generation_runs FROM wordweave_app")
	for _, response := range []testResponse{
		getJSON(t, adminClient, endpoint),
		putJSON(t, adminClient, endpoint+"/group", csrf, map[string]any{"group_code": "pro", "confirmed": true}),
	} {
		requireStatus(t, response, 500)
		if response.body["code"] != "internal_error" || response.body["data"] != nil || strings.Contains(response.raw, "generation_runs") {
			t.Fatal("unsafe partial/detail failure")
		}
	}
	var after time.Time
	var actualGroup string
	if err := pool.QueryRow(ctx, "SELECT group_code,quota_reset_at FROM wordweave.accounts WHERE id=$1", id).Scan(&actualGroup, &after); err != nil {
		t.Fatal(err)
	}
	if actualGroup != "registered" || !reset.Equal(after) {
		t.Fatal("read failure partially committed group change")
	}
	results := getJSON(t, adminClient, application.URL+"/api/v1/admin/users?username=quota")
	requireStatus(t, results, 200)
	if strings.Contains(results.raw, "generation_quota") {
		t.Fatal("search DTO expanded")
	}
	requireStatus(t, getJSON(t, adminClient, endpoint+"/batches"), 200)
	requireStatus(t, getJSON(t, adminClient, batchEndpoint), 200)
	quotaHTTPExec(t, ctx, pool, "GRANT SELECT ON wordweave.generation_runs TO wordweave_app")
	quotaHTTPExec(t, ctx, pool, "DELETE FROM wordweave.accounts WHERE id=$1", other)
	requireStatus(t, getJSON(t, adminClient, application.URL+"/api/v1/admin/users/"+other.String()), 404)
}

func quotaHTTPExec(t *testing.T, ctx context.Context, pool *pgxpool.Pool, query string, args ...any) {
	t.Helper()
	if _, err := pool.Exec(ctx, query, args...); err != nil {
		t.Fatal(err)
	}
}
func assertQuotaHTTP(t *testing.T, client *http.Client, endpoint, kind string, remaining int) testResponse {
	t.Helper()
	response, err := client.Get(endpoint)
	if err != nil {
		t.Fatal(err)
	}
	if response.Header.Get("Cache-Control") != "no-store" || response.Header.Get("Content-Type") != "application/json; charset=utf-8" {
		t.Fatal("private response headers changed")
	}
	decoded := decodeResponse(t, response)
	requireStatus(t, decoded, 200)
	if err := validateAdminQuotaEnvelope([]byte(decoded.raw), false); err != nil {
		t.Fatalf("wire contract: %v", err)
	}
	value := nestedValue(t, decoded.body, "data", "user", "generation_quota")
	if kind == "" {
		if value != nil {
			t.Fatal("admin quota must be null")
		}
		return decoded
	}
	quota := value.(map[string]any)
	if quota["kind"] != kind {
		t.Fatal("quota kind mismatch")
	}
	if kind == "limited" && quota["remaining"] != float64(remaining) {
		t.Fatalf("remaining=%v want=%d", quota["remaining"], remaining)
	}
	return decoded
}
func quotaHTTPBatch(t *testing.T, ctx context.Context, pool *pgxpool.Pool, owner, runID uuid.UUID) uuid.UUID {
	t.Helper()
	tx, err := pool.Begin(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	var batch, target uuid.UUID
	if err := tx.QueryRow(ctx, `INSERT INTO wordweave.learning_batches(owner_id,generation_run_id,group_code_snapshot,model_display_name_snapshot,provider_model_id_snapshot,
		meaning_language,scenario,length_code,passage,tags,expected_target_count,validator_version)
		VALUES ($1,$2,'registered','Quota fixture','test/quota','en','story','short','Learning works.',ARRAY['study'],1,'m001-v2') RETURNING id`, owner, runID).Scan(&batch); err != nil {
		t.Fatal(err)
	}
	if err := tx.QueryRow(ctx, `INSERT INTO wordweave.batch_targets(owner_id,batch_id,vocabulary_entry_id,source_entry_snapshot,input_order,entry_meaning,hint_phrase,hint_surface,hint_start,hint_end)
		SELECT $1,$2,id,'learn',0,'gain knowledge','learning together','learning',0,8 FROM wordweave.vocabulary_entries WHERE entry='learn' RETURNING id`, owner, batch).Scan(&target); err != nil {
		t.Fatal(err)
	}
	if _, err := tx.Exec(ctx, `INSERT INTO wordweave.hint_occurrences(owner_id,batch_id,target_id,occurrence_order,surface,start_offset,end_offset) VALUES ($1,$2,$3,0,'learning',0,8)`, owner, batch, target); err != nil {
		t.Fatal(err)
	}
	if _, err := tx.Exec(ctx, `INSERT INTO wordweave.passage_occurrences(owner_id,batch_id,target_id,occurrence_order,surface,start_offset,end_offset) VALUES ($1,$2,$3,0,'Learning',0,8)`, owner, batch, target); err != nil {
		t.Fatal(err)
	}
	if err := tx.Commit(ctx); err != nil {
		t.Fatal(err)
	}
	return batch
}

