	"strings"
	"sync/atomic"
	"testing"

	"wordweave/internal/ai"
)

func TestUATCaptureHTTPPreservesValidationAndQuota(t *testing.T) {
	for _, outcome := range []string{"invalid", "valid", "blocked_file", "other_subject", "unknown_relation", "hint_absent", "changed_configuration", "annotation_only", "annotation_other_subject", "annotation_blocked_file", "hint_only", "hint_only_valid", "hint_only_other_subject", "hint_only_blocked_file"} {
		t.Run(outcome, func(t *testing.T) {
			isValid := outcome == "valid" || outcome == "hint_only_valid"
			otherSubject := strings.HasSuffix(outcome, "other_subject")
			blockedFile := strings.HasSuffix(outcome, "blocked_file")
			ctx, api, pool, actor, model, cfg := cr039Harness(t)
			const secret = "synthetic-credential-never-in-capture"
			if err := api.credentials.Put(ctx, actor.ID, secret); err != nil {
				t.Fatal(err)
			}
			dir, ticket, _, _ := captureFixture(t)
			annotationOnly := strings.HasPrefix(outcome, "annotation_")
			hintOnly := strings.HasPrefix(outcome, "hint_only")
			filename := captureFilename
			if annotationOnly {
				t.Setenv("UAT_FAILURE_CAPTURE_DIR", "")
				t.Setenv("UAT_ANNOTATION_CAPTURE_DIR", dir)
				filename = annotationCaptureFilename
			}
			if hintOnly {
				t.Setenv("UAT_FAILURE_CAPTURE_DIR", "")
				t.Setenv("UAT_HINT_CAPTURE_DIR", dir)
				filename = hintCaptureFilename
			}
			ticket.ModelID = model.String()
			writeCaptureTicket(t, dir, ticket)
			candidate := ai.Candidate{
				Passage: strings.TrimSpace("Vulnerability(vulnerable)extra matters. " + strings.Repeat("Neighbors share useful ideas and practical support. ", 10)),
				Tags:    []string{"community"},
				Targets: []ai.CandidateTarget{{SourceEntry: "vulnerable", EntryMeaning: "open to harm",
					HintPhrase: "vulnerable(vulnerable) people"}},
			}
			if isValid || hintOnly {
				candidate.Passage = strings.Replace(candidate.Passage, ")extra", ")", 1)
			}
			expectedReason := "mapping_surface_absent"
			if hintOnly && !isValid {
				candidate.Targets[0].HintPhrase = "vulnerable (vulnerable) people"
				expectedReason = "hint_annotation_missing"
			}
			if annotationOnly {
				candidate.Passage = strings.Replace(candidate.Passage, "Vulnerability(vulnerable)extra", "Vulnerability(Vulnerable)", 1)
				expectedReason = "annotation_source_unknown"
			}
			if outcome == "unknown_relation" {
				candidate.Passage = strings.Replace(candidate.Passage, "Vulnerability(vulnerable)extra", "zznotarealwordzz(vulnerable)", 1)
				expectedReason = "mapping_relation_unknown"
			}
			if outcome == "hint_absent" {
				candidate.Passage = strings.Replace(candidate.Passage, ")extra", ")", 1)
				candidate.Targets[0].HintPhrase = "vulnerable(vulnerable)extra people"
			}
			language, scenario, length := "en", "discussion", "short"
			entries := []string{"vulnerable"}
			if outcome == "changed_configuration" {
				language, scenario, length = "ja", "news", "xlong"
				entries = []string{"young", "grape", "weekend", "danger", "enforce"}
				candidate.Passage = "Young(young) people pick a grape(grape)extra each weekend(weekend) and avoid danger(danger) as they enforce(enforce) the rules. " +
					strings.TrimSpace(strings.Repeat("Neighbors share useful ideas and practical support. ", 200))
				candidate.Tags = []string{"学習"}
				candidate.Targets = nil
				for _, entry := range entries {
					candidate.Targets = append(candidate.Targets, ai.CandidateTarget{
						SourceEntry: entry, EntryMeaning: "学ぶ", HintPhrase: entry + "(" + entry + ") examples",
					})
				}
			}
			var calls atomic.Int32
			provider := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				calls.Add(1)
				raw, _ := json.Marshal(candidate)
				chunk, _ := json.Marshal(map[string]any{"choices": []any{map[string]any{"delta": map[string]string{"content": string(raw)}}}})
				w.Header().Set("Content-Type", "text/event-stream")
				fmt.Fprintf(w, "data: %s\n\ndata: [DONE]\n\n", chunk)
			}))
			defer provider.Close()
			cfg.OpenRouterBaseURL = provider.URL
			cfg.PublicOrigin = "http://localhost:6001"
			api, err := New(cfg, pool, pool)
			if err != nil {
				t.Fatal(err)
			}
			defer func() { api.failureCapture.Close() }()
			application := httptest.NewServer(api.Handler())
			defer application.Close()
			client := newBrowserClient(t)
			csrf := bootstrap(t, client, application.URL)
			headers := map[string]string{"Origin": cfg.PublicOrigin}
			registered := decodeResponse(t, rawJSONRequest(t, client, http.MethodPost, application.URL+"/api/v1/auth/register", csrf,
				map[string]any{"username": "capture_learner", "password": "synthetic-password-123", "password_confirmation": "synthetic-password-123", "ui_locale": "en-US"}, headers))
			requireStatus(t, registered, http.StatusCreated)
			csrf = dataString(t, registered.body, "csrf_token")
			var registeredID string
			if err := pool.QueryRow(ctx, "SELECT id::text FROM wordweave.accounts WHERE username='capture_learner'").Scan(&registeredID); err != nil {
				t.Fatal(err)
			}
			if !otherSubject {
				api.failureCapture.Close()
				ticket.SubjectHash = captureSubjectHash("account:" + registeredID)
				writeCaptureTicket(t, dir, ticket)
				api.failureCapture, err = newFailureCapture(cfg.PublicOrigin)
				if err != nil {
					t.Fatal(err)
				}
			}
			if blockedFile {
				if err := os.Mkdir(filepath.Join(dir, filename), 0o700); err != nil {
					t.Fatal(err)
				}
			}
			response := rawJSONRequest(t, client, http.MethodPost, application.URL+"/api/v1/generations/stream", csrf,
				map[string]any{"model_id": model.String(), "meaning_language": language, "scenario": scenario, "length": length, "entries": entries}, headers)
			if response.StatusCode != 200 {
				response.Body.Close()
				t.Fatalf("stream HTTP status %d", response.StatusCode)
			}
			raw, err := io.ReadAll(response.Body)
			response.Body.Close()
			if err != nil {
				t.Fatal(err)
			}
			runID, token, valid := readGenerationSSE(t, strings.NewReader(string(raw)))
			if calls.Load() != 1 || runID == "" || valid != isValid {
				t.Fatal("stream terminal result or provider call count changed")
			}
			var drafts, batches int
			var charged bool
			if err := pool.QueryRow(ctx, `SELECT (SELECT count(*) FROM wordweave.generation_drafts),(SELECT count(*) FROM wordweave.learning_batches),quota_charged FROM wordweave.generation_runs WHERE id=$1`, runID).Scan(&drafts, &batches, &charged); err != nil {
				t.Fatal(err)
			}
			if batches != 0 || charged != isValid || drafts != map[bool]int{true: 1, false: 0}[isValid] {
				t.Fatal("capture changed persistence or accounting")
			}
			if isValid {
				assertNoCapture(t, dir)
				if hintOnly {
					assertNoHint(t, dir)
				}
				return
			}
			if strings.Count(string(raw), "event: generation.failed") != 1 || !strings.Contains(string(raw), `"quota_refunded":true`) ||
				strings.Contains(string(raw), "passage_forms") || strings.Contains(string(raw), "hint_phrase") || strings.Contains(string(raw), "(vulnerable)") || strings.Contains(string(raw), "(grape)") {
				t.Fatal("failure SSE changed or leaked private candidate")
			}
			if otherSubject {
				assertNoCapture(t, dir)
				if annotationOnly {
					assertNoAnnotation(t, dir)
				}
				if hintOnly {
					assertNoHint(t, dir)
				}
				return
			}
			if blockedFile {
				info, err := os.Stat(filepath.Join(dir, filename))
				if err != nil || !info.IsDir() {
					t.Fatal("capture altered blocked output")
				}
				return
			}
			sample, err := os.ReadFile(filepath.Join(dir, filename))
			if err != nil {
				t.Fatal(err)
			}
			if annotationOnly {
				var sampleFields map[string]json.RawMessage
				var projected ai.AnnotationSourceDiagnostic
				if json.Unmarshal(sample, &sampleFields) != nil || len(sampleFields) != 7 || json.Unmarshal(sampleFields["annotation"], &projected) != nil || projected.SourceLabel != "Vulnerable" || projected.AdjacentWord != "Vulnerability" {
					t.Fatal("wrong minimal annotation sample")
				}
				for _, forbidden := range []string{candidate.Passage, candidate.Targets[0].HintPhrase, candidate.Targets[0].EntryMeaning, secret, token, registeredID, ticket.SubjectHash, "configuration", "candidate"} {
					if strings.Contains(string(sample), forbidden) {
						t.Fatal("minimal capture leaked content or credentials")
					}
				}
				assertNoCapture(t, dir)
				return
			}
			if hintOnly {
				var fields map[string]json.RawMessage
				var hint, reason string
				if json.Unmarshal(sample, &fields) != nil || len(fields) != 8 ||
					json.Unmarshal(fields["hint_phrase"], &hint) != nil || hint != candidate.Targets[0].HintPhrase ||
					json.Unmarshal(fields["reason"], &reason) != nil || reason != expectedReason {
					t.Fatal("wrong hint-only projection")
				}
				for _, forbidden := range []string{candidate.Passage, candidate.Targets[0].EntryMeaning, secret, token, registeredID, ticket.SubjectHash, "configuration", "candidate"} {
					if strings.Contains(string(sample), forbidden) {
						t.Fatal("hint capture leaked unrelated content or credentials")
					}
				}
				assertNoAnnotation(t, dir)
				return
			}
			var got struct {
				Candidate     ai.Candidate         `json:"candidate"`
				Reason        string               `json:"reason"`
				RunID         string               `json:"run_id"`
				Configuration captureConfiguration `json:"configuration"`
			}
			if json.Unmarshal(sample, &got) != nil || got.RunID != runID || got.Reason != expectedReason ||
				got.Candidate.Passage != candidate.Passage ||
				got.Candidate.Targets[0].HintPhrase != candidate.Targets[0].HintPhrase ||
				got.Configuration.MeaningLanguage != language || got.Configuration.Scenario != scenario || got.Configuration.Length != length {
				t.Fatal("private candidate missing original wrong declaration")
			}
			if strings.Contains(string(sample), secret) || strings.Contains(string(sample), token) || strings.Contains(string(sample), "capture_learner") || strings.Contains(string(sample), registeredID) || strings.Contains(string(sample), ticket.SubjectHash) {
				t.Fatal("capture leaked request or credentials")
			}
		})
	}
}

//go:build uatdiagnostics

package httpapi

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
	"unicode/utf8"

	"github.com/google/uuid"

	"wordweave/internal/ai"
)

const captureFilename = "failure.json"
const captureMaxBytes = 1 << 20
const annotationCaptureFilename = "annotation.json"
const annotationClaimFilename = "annotation.claimed"
const hintCaptureFilename = "hint.json"
const hintClaimFilename = "hint.claimed"
const minimalCaptureFilename = "sample.json"
const minimalClaimFilename = "sample.claimed"

// A private ticket binds the approved testing identity and model, not its inputs.
type captureTicket struct {
	ExpiresAt   time.Time `json:"expires_at"`
	ModelID     string    `json:"model_id"`
	SubjectHash string    `json:"subject_hash"`
}

// Called with the server-resolved identity, never a client-supplied subject.
// Neither the identity nor its hash is included in the sample or normal logs.
func captureSubjectHash(subject string) string {
	kind, id, ok := strings.Cut(subject, ":")
	parsed, err := uuid.Parse(id)
	if !ok || (kind != "account" && kind != "visitor") || err != nil || parsed == uuid.Nil {
		return ""
	}
	digest := sha256.Sum256([]byte("wordweave-uat-capture:" + kind + ":" + parsed.String()))
	return hex.EncodeToString(digest[:])
}

type uatFailureCapture struct {
	minimal        bool
	annotationOnly bool
	hintOnly       bool
	mu             sync.Mutex
	root           *os.Root
	ticket         captureTicket
	timer          *time.Timer
	claimed        bool
	closed         bool
}

func newFailureCapture(origin string) (failureCapture, error) {
	directory := os.Getenv("UAT_FAILURE_CAPTURE_DIR")
	annotationDirectory := os.Getenv("UAT_ANNOTATION_CAPTURE_DIR")
	hintDirectory := os.Getenv("UAT_HINT_CAPTURE_DIR")
	minimalDirectory := os.Getenv("UAT_MINIMAL_CAPTURE_DIR")
	configured := 0
	for _, path := range []string{directory, annotationDirectory, hintDirectory, minimalDirectory} {
		if path != "" {
			configured++
		}
	}
	if configured > 1 {
		return nil, errors.New("conflicting private UAT capture configuration")
	}
	annotationOnly := annotationDirectory != ""
	hintOnly := hintDirectory != ""
	if annotationOnly {
		directory = annotationDirectory
	}
	if hintOnly {
		directory = hintDirectory
	}
	if minimalDirectory != "" {
		directory = minimalDirectory
	}
	if directory == "" {
		return nil, nil
	}
	// Do not include paths, ticket contents, or wrapped filesystem errors in logs.
	invalid := errors.New("invalid private UAT failure capture configuration")
	parsed, err := url.Parse(origin)
	if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") {
		return nil, invalid
	}
	host := parsed.Hostname()
	if host != "localhost" && !net.ParseIP(host).IsLoopback() {
		return nil, invalid
	}
	if !filepath.IsAbs(directory) {
		return nil, invalid
	}
	info, err := os.Lstat(directory)
	if err != nil || !info.IsDir() || info.Mode().Perm() != 0o700 {
		return nil, invalid
	}
	root, err := os.OpenRoot(directory)
	if err != nil {
		return nil, invalid
	}
	accepted := false
	defer func() {
		if !accepted {
			_ = root.Close()
		}
	}()
	info, err = root.Lstat("ticket.json")
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 || info.Size() > 4096 {
		return nil, invalid
	}
	file, err := root.Open("ticket.json")
	if err != nil {
		return nil, invalid
	}
	raw, readErr := io.ReadAll(io.LimitReader(file, 4097))
	_ = file.Close()
	if readErr != nil || len(raw) > 4096 {
		return nil, invalid
	}
	var ticket captureTicket
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if decoder.Decode(&ticket) != nil || decoder.Decode(new(any)) != io.EOF {
		return nil, invalid
	}
	subjectDigest, digestErr := hex.DecodeString(ticket.SubjectHash)
	if ticket.ExpiresAt.IsZero() || ticket.ModelID == "" || digestErr != nil ||
		len(subjectDigest) != sha256.Size || hex.EncodeToString(subjectDigest) != ticket.SubjectHash {
		return nil, invalid
	}
	remaining := time.Until(ticket.ExpiresAt)
	if remaining > time.Hour {
		return nil, invalid
	}
	capture := &uatFailureCapture{root: root, ticket: ticket, minimal: minimalDirectory != "", annotationOnly: annotationOnly, hintOnly: hintOnly}
	if info, err := root.Lstat(capture.filename()); err == nil {
		// Restarting the same ticket must not overwrite or collect another sample.
		if !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 {
			return nil, invalid
		}
		capture.claimed = true
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, invalid
	}
	if capture.minimal || annotationOnly || hintOnly {
		if info, err := root.Lstat(capture.claimFilename()); err == nil {
			if !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 || info.Size() != 0 {
				return nil, invalid
			}
			capture.claimed = true
		} else if !errors.Is(err, os.ErrNotExist) {
			return nil, invalid
		}
	}
	accepted = true
	if remaining <= 0 {
		capture.Close()
		return nil, nil
	}
	capture.mu.Lock()
	capture.timer = time.AfterFunc(remaining, capture.Close)
	capture.mu.Unlock()
	return capture, nil
}

func (capture *uatFailureCapture) Record(subject string, spec ai.GenerationSpec, candidate ai.Candidate, reason string, targetIndex int) {
	capture.mu.Lock()
	defer capture.mu.Unlock()
	if capture.closed || capture.claimed || !time.Now().Before(capture.ticket.ExpiresAt) ||
		spec.CompatibilityProbe || spec.ModelID != capture.ticket.ModelID ||
		captureSubjectHash(subject) != capture.ticket.SubjectHash {
		return
	}
	if capture.minimal {
		// Both approved projections compete for the SAME file and persistent
		// claim. Never fall back to full-candidate capture for another reason.
		switch reason {
		case "annotation_source_unknown":
			capture.recordAnnotation(spec, candidate, reason, targetIndex)
		case "hint_annotation_missing":
			capture.recordHint(spec, candidate, reason, targetIndex)
		}
		return
	}
	if capture.annotationOnly {
		capture.recordAnnotation(spec, candidate, reason, targetIndex)
		return
	}
	if capture.hintOnly {
		capture.recordHint(spec, candidate, reason, targetIndex)
		return
	}
	capture.claimed = true
	// Explicit allowlist: no request, actor, token, headers, credentials or error.Error().
	raw, err := json.MarshalIndent(struct {
		RunID            string               `json:"run_id"`
		CapturedAt       time.Time            `json:"captured_at"`
		ExpiresAt        time.Time            `json:"expires_at"`
		PromptVersion    string               `json:"prompt_version"`
		ValidatorVersion string               `json:"validator_version"`
		Reason           string               `json:"reason"`
		TargetIndex      int                  `json:"target_index"`
		Configuration    captureConfiguration `json:"configuration"`
		Candidate        ai.Candidate         `json:"candidate"`
	}{spec.RunID, time.Now().UTC(), capture.ticket.ExpiresAt, spec.PromptVersion,
		ai.ValidatorVersion, reason, targetIndex, captureConfiguration{
			spec.ModelID, spec.MeaningLanguage, spec.Scenario, spec.LengthCode,
			spec.MinimumWords, append([]string(nil), spec.Entries...),
		}, candidate}, "", "  ")
	if err != nil || len(raw) > captureMaxBytes {
		slog.Warn("uat_failure_capture_skipped", "reason", "sample_size_or_encoding")
		return
	}
	if !time.Now().Before(capture.ticket.ExpiresAt) {
		return
	}
	file, err := capture.root.OpenFile(captureFilename, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		slog.Warn("uat_failure_capture_skipped", "reason", "private_file_unavailable")
		return
	}
	_, writeErr := file.Write(raw)
	closeErr := file.Close()
	if writeErr != nil || closeErr != nil {
		_ = capture.root.Remove(captureFilename)
		slog.Warn("uat_failure_capture_skipped", "reason", "private_file_write_failed")
		return
	}
	slog.Info("uat_failure_candidate_captured", "run_id", spec.RunID)
}

// Only non-secret generation parameters needed for exact offline validation.
type captureConfiguration struct {
	ModelID         string   `json:"model_id"`
	MeaningLanguage string   `json:"meaning_language"`
	Scenario        string   `json:"scenario"`
	Length          string   `json:"length"`
	MinimumWords    int      `json:"minimum_words"`
	Entries         []string `json:"entries"`
}

func (capture *uatFailureCapture) Close() {
	capture.mu.Lock()
	defer capture.mu.Unlock()
	if capture.closed {
		return
	}
	capture.closed = true
	if capture.timer != nil {
		capture.timer.Stop()
	}
	if err := capture.root.Remove(capture.filename()); err != nil && !errors.Is(err, os.ErrNotExist) {
		slog.Warn("uat_failure_capture_cleanup_failed")
	}
	_ = capture.root.Close()
}

func (capture *uatFailureCapture) filename() string {
	if capture.minimal {
		return minimalCaptureFilename
	}
	if capture.hintOnly {
		return hintCaptureFilename
	}
	if capture.annotationOnly {
		return annotationCaptureFilename
	}
	return captureFilename
}

func (capture *uatFailureCapture) claimFilename() string {
	if capture.minimal {
		return minimalClaimFilename
	}
	if capture.hintOnly {
		return hintClaimFilename
	}
	return annotationClaimFilename
}

// Called only after failed validation and identity/model/expiry checks. Capture
// the one indexed raw hint verbatim, not its siblings or any passage/meaning.
func (capture *uatFailureCapture) recordHint(spec ai.GenerationSpec, candidate ai.Candidate, reason string, targetIndex int) {
	if reason != "hint_annotation_missing" || targetIndex < 0 || targetIndex >= len(spec.Entries) || targetIndex >= len(candidate.Targets) {
		return
	}
	target := candidate.Targets[targetIndex]
	if target.SourceEntry != spec.Entries[targetIndex] || target.HintPhrase == "" ||
		!utf8.ValidString(target.HintPhrase) || utf8.RuneCountInString(target.HintPhrase) > 500 {
		return
	}
	raw, err := json.Marshal(struct {
		RunID            string    `json:"run_id"`
		CapturedAt       time.Time `json:"captured_at"`
		ExpiresAt        time.Time `json:"expires_at"`
		PromptVersion    string    `json:"prompt_version"`
		ValidatorVersion string    `json:"validator_version"`
		Reason           string    `json:"reason"`
		TargetIndex      int       `json:"target_index"`
		HintPhrase       string    `json:"hint_phrase"`
	}{spec.RunID, time.Now().UTC(), capture.ticket.ExpiresAt, spec.PromptVersion,
		ai.ValidatorVersion, reason, targetIndex, target.HintPhrase})
	if err != nil {
		return
	}
	capture.recordMinimal(spec.RunID, raw)
}

// Called under capture.mu after identity/model/probe/expiry checks. The empty
// claim survives sample deletion and process restart; it contains no content.
func (capture *uatFailureCapture) recordAnnotation(spec ai.GenerationSpec, candidate ai.Candidate, reason string, targetIndex int) {
	if reason != "annotation_source_unknown" || targetIndex != -1 {
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	diagnostic, ok := ai.InspectUnknownAnnotation(ctx, candidate.Passage, spec.Entries)
	if !ok || !time.Now().Before(capture.ticket.ExpiresAt) {
		return
	}
	raw, err := json.Marshal(struct {
		RunID            string                        `json:"run_id"`
		CapturedAt       time.Time                     `json:"captured_at"`
		ExpiresAt        time.Time                     `json:"expires_at"`
		PromptVersion    string                        `json:"prompt_version"`
		ValidatorVersion string                        `json:"validator_version"`
		Reason           string                        `json:"reason"`
		Annotation       ai.AnnotationSourceDiagnostic `json:"annotation"`
	}{spec.RunID, time.Now().UTC(), capture.ticket.ExpiresAt, spec.PromptVersion, ai.ValidatorVersion, reason, diagnostic})
	if err != nil || len(raw) > 4096 {
		return
	}
	capture.recordMinimal(spec.RunID, raw)
}

func (capture *uatFailureCapture) recordMinimal(runID string, raw []byte) {
	if len(raw) > 4096 || !time.Now().Before(capture.ticket.ExpiresAt) {
		return
	}
	capture.claimed = true
	claim, err := capture.root.OpenFile(capture.claimFilename(), os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return
	}
	if claim.Close() != nil || !time.Now().Before(capture.ticket.ExpiresAt) {
		return
	}
	file, err := capture.root.OpenFile(capture.filename(), os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		slog.Warn("uat_minimal_capture_skipped", "reason", "private_file_unavailable")
		return
	}
	_, writeErr := file.Write(raw)
	closeErr := file.Close()
	if writeErr != nil || closeErr != nil {
		_ = capture.root.Remove(capture.filename())
		slog.Warn("uat_minimal_capture_skipped", "reason", "private_file_write_failed")
		return
	}
	slog.Info("uat_minimal_captured", "run_id", runID)
}

