func TestUATCaptureExactCandidateAndPrivateOutput(t *testing.T) {
	dir, _, spec, candidate := captureFixture(t)
	capture := openTestCapture(t)
	var logs bytes.Buffer
	previous := slog.Default()
	slog.SetDefault(slog.New(slog.NewJSONHandler(&logs, nil)))
	defer slog.SetDefault(previous)
	capture.Record(captureTestSubject, spec, candidate, "mapping_surface_absent", 0)
	raw, err := os.ReadFile(filepath.Join(dir, captureFilename))
	if err != nil {
		t.Fatal(err)
	}
	var got struct {
		RunID       string       `json:"run_id"`
		Reason      string       `json:"reason"`
		TargetIndex int          `json:"target_index"`
		Candidate   ai.Candidate `json:"candidate"`
	}
	if json.Unmarshal(raw, &got) != nil || got.RunID != spec.RunID ||
		got.Reason != "mapping_surface_absent" || got.TargetIndex != 0 || !reflect.DeepEqual(got.Candidate, candidate) {
		t.Fatal("candidate or diagnosis changed during capture")
	}
	info, err := os.Stat(filepath.Join(dir, captureFilename))
	if err != nil || info.Mode().Perm() != 0o600 {
		t.Fatal("sample is not private")
	}
	for _, forbidden := range []string{"authorization", "generation_token", "account_id", "password", "api_key"} {
		if strings.Contains(string(raw), forbidden) {
			t.Fatalf("unexpected captured field: %s", forbidden)
		}
	}
	for _, forbidden := range []string{candidate.Passage, candidate.Targets[0].HintPhrase, candidate.Targets[0].EntryMeaning, "passage_forms", dir} {
		if strings.Contains(logs.String(), forbidden) {
			t.Fatal("ordinary log leaked captured content")
		}
	}
	capture.Close()
	assertNoCapture(t, dir)
}

func TestUATCaptureScopeAndConcurrency(t *testing.T) {
	dir, _, spec, candidate := captureFixture(t)
	capture := openTestCapture(t)
	for _, mutate := range []func(*ai.GenerationSpec){
		func(s *ai.GenerationSpec) { s.ModelID = "other" },
		func(s *ai.GenerationSpec) { s.CompatibilityProbe = true },
	} {
		other := spec
		mutate(&other)
		capture.Record(captureTestSubject, other, candidate, "mapping_surface_absent", 0)
		assertNoCapture(t, dir)
	}
	var workers sync.WaitGroup
	for range 20 {
		workers.Go(func() { capture.Record(captureTestSubject, spec, candidate, "mapping_surface_absent", 0) })
	}
	workers.Wait()
	before, err := os.ReadFile(filepath.Join(dir, captureFilename))
	if err != nil {
		t.Fatal(err)
	}
	candidate.Passage = "Do not overwrite the original sample."
	capture.Record(captureTestSubject, spec, candidate, "mapping_surface_absent", 0)
	after, err := os.ReadFile(filepath.Join(dir, captureFilename))
	if err != nil || !bytes.Equal(before, after) {
		t.Fatal("single sample overwritten")
	}
}

func TestUATCaptureExpiresAndCannotReopen(t *testing.T) {
	dir, ticket, spec, candidate := captureFixture(t)
	ticket.ExpiresAt = time.Now().Add(150 * time.Millisecond)
	writeCaptureTicket(t, dir, ticket)
	capture := openTestCapture(t)
	capture.Record(captureTestSubject, spec, candidate, "mapping_surface_absent", 0)
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		if _, err := os.Stat(filepath.Join(dir, captureFilename)); os.IsNotExist(err) {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	assertNoCapture(t, dir)
	capture.Record(captureTestSubject, spec, candidate, "mapping_surface_absent", 0)
	assertNoCapture(t, dir)
	reopened, err := newFailureCapture("http://localhost:6001")
	if err != nil || reopened != nil {
		t.Fatal("expired ticket reopened")
	}
}

func TestUATCaptureInvalidConfiguration(t *testing.T) {
	for _, name := range []string{"remote_origin", "directory_permissions", "ticket_permissions", "ticket_symlink", "directory_symlink", "unknown_field", "oversized_ticket", "missing_expiry", "long_expiry", "output_symlink", "missing_subject", "malformed_subject", "uppercase_subject"} {
		t.Run(name, func(t *testing.T) {
			dir, ticket, _, _ := captureFixture(t)
			origin := "http://127.0.0.1:6001"
			switch name {
			case "remote_origin":
				origin = "https://example.com"
			case "directory_permissions":
				if err := os.Chmod(dir, 0o755); err != nil {
					t.Fatal(err)
				}
			case "ticket_permissions":
				if err := os.Chmod(filepath.Join(dir, "ticket.json"), 0o644); err != nil {
					t.Fatal(err)
				}
			case "ticket_symlink":
				if err := os.Rename(filepath.Join(dir, "ticket.json"), filepath.Join(dir, "real.json")); err != nil {
					t.Fatal(err)
				}
				if err := os.Symlink("real.json", filepath.Join(dir, "ticket.json")); err != nil {
					t.Fatal(err)
				}
			case "directory_symlink":
				link := filepath.Join(t.TempDir(), "linked")
				if err := os.Symlink(dir, link); err != nil {
					t.Fatal(err)
				}
				t.Setenv("UAT_FAILURE_CAPTURE_DIR", link)
			case "unknown_field":
				if err := os.WriteFile(filepath.Join(dir, "ticket.json"), []byte(`{"api_key":"must-not-log"}`), 0o600); err != nil {
					t.Fatal(err)
				}
			case "oversized_ticket":
				if err := os.WriteFile(filepath.Join(dir, "ticket.json"), []byte(strings.Repeat(" ", 4097)), 0o600); err != nil {
					t.Fatal(err)
				}
			case "missing_expiry":
				ticket.ExpiresAt = time.Time{}
				writeCaptureTicket(t, dir, ticket)
			case "long_expiry":
				ticket.ExpiresAt = time.Now().Add(2 * time.Hour)
				writeCaptureTicket(t, dir, ticket)
			case "missing_subject":
				ticket.SubjectHash = ""
				writeCaptureTicket(t, dir, ticket)
			case "malformed_subject":
				ticket.SubjectHash = strings.Repeat("z", 64)
				writeCaptureTicket(t, dir, ticket)
			case "uppercase_subject":
				ticket.SubjectHash = strings.ToUpper(ticket.SubjectHash)
				writeCaptureTicket(t, dir, ticket)
			case "output_symlink":
				if err := os.Symlink("ticket.json", filepath.Join(dir, captureFilename)); err != nil {
					t.Fatal(err)
				}
			}
			got, err := newFailureCapture(origin)
			if got != nil {
				got.Close()
			}
			if err == nil {
				t.Fatal("unsafe capture configuration accepted")
			}
			if strings.Contains(err.Error(), dir) || strings.Contains(err.Error(), "must-not-log") {
				t.Fatal("configuration error leaks contents")
			}
		})
	}
}

