func TestBoundarySlowStreamHTTP(t *testing.T) {
	if os.Getenv("WORDWEAVE_SLOW_STREAM_TESTS") != "1" {
		t.Skip("explicit 60/120-second synthetic test")
	}
	for _, duration := range []time.Duration{60 * time.Second, 120 * time.Second} {
		t.Run(duration.String(), func(t *testing.T) {
			t.Parallel()
			candidate := ai.Candidate{
				Passage: "Young(young) people share grapes(grape). " + strings.TrimSpace(strings.Repeat("Neighbors offer practical ideas and helpful support. ", 9)),
				Tags:    []string{"fruit"},
				Targets: []ai.CandidateTarget{
					{SourceEntry: "grape", EntryMeaning: "a small fruit", HintPhrase: "fresh grapes(grape)"},
					{SourceEntry: "young", EntryMeaning: "not old", HintPhrase: "young(young) children"},
				},
			}
			document := p0HTTPJSON(candidate)
			split := len(document) / 2
			f := newBoundaryHTTPFixture(t, func(w http.ResponseWriter, r *http.Request) {
				w.Header().Set("Content-Type", "text/event-stream")
				fmt.Fprint(w, boundaryDelta(document[:split]))
				w.(http.Flusher).Flush()
				timer := time.NewTimer(duration)
				defer timer.Stop()
				select {
				case <-r.Context().Done():
					return
				case <-timer.C:
				}
				fmt.Fprint(w, boundaryDelta(document[split:])+"data: [DONE]\n\n")
			})
			began := time.Now()
			response := f.start(t)
			defer response.Body.Close()
			scanner := bufio.NewScanner(response.Body)
			var stream strings.Builder
			var final generationResultDTO
			var heartbeatTimes []time.Duration
			var firstDelta time.Duration
			event := ""
			terminals := 0
			for scanner.Scan() {
				line := scanner.Text()
				if line == ": heartbeat" {
					heartbeatTimes = append(heartbeatTimes, time.Since(began))
				}
				if strings.HasPrefix(line, "event: ") {
					event = strings.TrimPrefix(line, "event: ")
				}
				if !strings.HasPrefix(line, "data: ") {
					continue
				}
				data := []byte(strings.TrimPrefix(line, "data: "))
				switch event {
				case "passage.delta":
					var delta struct {
						Text string `json:"text"`
					}
					if err := json.Unmarshal(data, &delta); err != nil {
						t.Fatal(err)
					}
					if firstDelta == 0 {
						firstDelta = time.Since(began)
					}
					stream.WriteString(delta.Text)
				case "generation.validated":
					var result struct {
						Result generationResultDTO `json:"result"`
					}
					if err := json.Unmarshal(data, &result); err != nil {
						t.Fatal(err)
					}
					final = result.Result
					terminals++
				case "generation.failed", "generation.cancelled":
					t.Fatal("slow generation ended as failure")
				}
			}
			elapsed := time.Since(began)
			if scanner.Err() != nil {
				t.Fatal(scanner.Err())
			}
			if elapsed < duration || elapsed > duration+10*time.Second || firstDelta == 0 || firstDelta > 3*time.Second || terminals != 1 {
				t.Fatalf("timing/terminal mismatch: elapsed=%s first=%s terminal=%d", elapsed, firstDelta, terminals)
			}
			if len(heartbeatTimes) < int(duration/(15*time.Second))-1 {
				t.Fatalf("missing heartbeat: %v", heartbeatTimes)
			}
			previous := time.Duration(0)
			for _, at := range heartbeatTimes {
				interval := at - previous
				if interval < 12*time.Second || interval > 18*time.Second {
					t.Fatalf("heartbeat interval %s", interval)
				}
				previous = at
			}
			if stream.String() != final.Passage || strings.Contains(final.Passage, "(grape)") || strings.Contains(final.Passage, "(young)") || len(final.Targets) != 2 {
				t.Fatal("clean streamed result contract changed")
			}
			f.assertSettled(t, "valid", true, 1)
			t.Logf("elapsed=%s first_delta=%s heartbeat_count=%d terminal=validated stream_equals_final=true", elapsed, firstDelta, len(heartbeatTimes))
		})
	}
}

package generationevidence

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"sync"
	"testing"
	"time"

	gt "wordweave/internal/generationtrace"
)

func TestOBS042BConcurrentRotationNeverExceeds50(t *testing.T) {
	m, p := testManager(t)
	var wg sync.WaitGroup
	for i := 0; i < 64; i++ {
		wg.Go(func() {
			b := m.Admit("account", DedicatedAccountID, "req_concurrent", time.Now())
			if b == nil {
				t.Error("admission failed")
			}
		})
	}
	wg.Wait()
	if len(m.IDs()) != 50 {
		t.Fatal("in-memory bound")
	}
	files, err := filepath.Glob(filepath.Join(p, "*.jsonl"))
	if err != nil || len(files) != 50 {
		t.Fatal("on-disk bound", err, len(files))
	}
}
func TestOBS042BCloseFailureRemainsAnErrorAndRestartCleans(t *testing.T) {
	p := privateDirectory(t)
	m, err := Open(Options{p, testFingerprint()})
	if err != nil {
		t.Fatal(err)
	}
	b := admit(t, m)
	m.mu.Lock()
	m.remove = func(Manifest) error { return ErrCleanup }
	m.mu.Unlock()
	for i := 0; i < 2; i++ {
		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
		err = m.Close(ctx)
		cancel()
		if !errors.Is(err, ErrCleanup) {
			t.Fatal("cleanup failure swallowed", err)
		}
	}
	if _, err = Read(p, b.ID(), time.Now()); !errors.Is(err, ErrCleanup) {
		t.Fatal("shutdown failure read allowed")
	}
	m, err = Open(Options{p, testFingerprint()})
	if err != nil {
		t.Fatal(err)
	}
	if len(m.IDs()) != 0 {
		t.Fatal("failed-close data exposed at restart")
	}
	if err = m.Close(context.Background()); err != nil {
		t.Fatal(err)
	}
	if _, err = os.Stat(filepath.Join(p, b.ID()+".jsonl")); !errors.Is(err, os.ErrNotExist) {
		t.Fatal("recovery did not remove")
	}
}
func TestOBS042BRepeatedProgressIsCoalescedButFailuresAndUsageRemain(t *testing.T) {
	m, p := testManager(t)
	b := admit(t, m)
	for i := 0; i < 1000; i++ {
		b.Event(gt.Event{Kind: "fact", Fact: gt.StageFact{Stage: gt.ProviderStream.String(), Check: "frame", Detail: gt.Detail{Actual: i}}})
		b.Event(gt.Event{Kind: "fact", Fact: gt.StageFact{Stage: gt.ProviderStream.String(), Check: "content", Detail: gt.Detail{Actual: i * 10}}})
		b.Event(gt.Event{Kind: "provider", Fact: gt.StageFact{Stage: gt.ProviderStream.String()}, Provider: &gt.ProviderFact{Frame: int64(i), ID: "gen_fixture", FinishReason: "not_provided", SyntaxOffset: -1}})
	}
	b.Event(gt.Event{Kind: "provider", Fact: gt.StageFact{Stage: gt.ProviderStream.String()}, Provider: &gt.ProviderFact{UsageProvided: true, TotalTokens: 10}})
	b.Event(gt.Event{Kind: "stage_end", Fact: gt.StageFact{Stage: gt.ContentValidate.String(), State: gt.Failed, Detail: gt.Why("hint_annotation_missing")}})
	finish(t, b)
	view, err := Read(p, b.ID(), time.Now())
	if err != nil {
		t.Fatal(err)
	}
	usage, failure, progress := false, false, false
	for _, r := range view.Records {
		if r.Event != nil {
			if r.Event.Provider != nil && r.Event.Provider.UsageProvided {
				usage = true
			}
			if r.Event.Fact.Detail.Reason == "hint_annotation_missing" {
				failure = true
			}
		}
		if r.State != nil {
			if r.State.Truncated || r.State.DroppedRecords != 0 || r.State.CoalescedProgress != 2999 {
				t.Fatalf("bad coalescing: %+v", r.State)
			}
			if len(r.Progress) != 3 || r.Progress[0].Fact.Detail.Actual != 999 || r.Progress[1].Fact.Detail.Actual != 9990 {
				t.Fatal("latest counters lost")
			}
			progress = true
		}
	}
	if !usage || !failure || !progress || !b.ByteExact() {
		t.Fatal("coalescing discarded meaningful evidence")
	}
}

package generationevidence

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"time"

	"github.com/google/uuid"
	"golang.org/x/sys/unix"
)

type disk struct {
	root *os.Root
	lock *os.File
}

func openDisk(path string) (*disk, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) == string(filepath.Separator) {
		return nil, ErrUnsafe
	}
	canonical, err := filepath.EvalSymlinks(path)
	if err != nil || canonical != path {
		return nil, ErrUnsafe
	}
	info, err := os.Lstat(path)
	if err != nil || !info.IsDir() || info.Mode().Perm() != 0700 || !owned(info) {
		return nil, ErrUnsafe
	}
	root, err := os.OpenRoot(path)
	if err != nil {
		return nil, ErrUnsafe
	}
	d := &disk{root: root}
	lock, err := root.OpenFile(".lock", os.O_CREATE|os.O_RDWR, 0600)
	if err != nil {
		root.Close()
		return nil, ErrUnsafe
	}
	d.lock = lock
	if !d.validFile(".lock", lock) {
		d.close()
		return nil, ErrUnsafe
	}
	return d, nil
}
func owned(info os.FileInfo) bool {
	s, ok := info.Sys().(*syscall.Stat_t)
	return ok && s.Uid == uint32(os.Geteuid())
}
func (d *disk) validFile(name string, f *os.File) bool {
	before, err := d.root.Lstat(name)
	if err != nil || !before.Mode().IsRegular() || before.Mode().Perm() != 0600 || !owned(before) {
		return false
	}
	actual, err := f.Stat()
	if err != nil || !os.SameFile(before, actual) {
		return false
	}
	s, ok := actual.Sys().(*syscall.Stat_t)
	return ok && s.Nlink == 1
}
func (d *disk) acquire() error {
	if unix.Flock(int(d.lock.Fd()), unix.LOCK_EX|unix.LOCK_NB) != nil {
		return ErrBusy
	}
	return nil
}
func (d *disk) release() { _ = unix.Flock(int(d.lock.Fd()), unix.LOCK_UN) }
func (d *disk) close() {
	if d.lock != nil {
		_ = d.lock.Close()
	}
	if d.root != nil {
		_ = d.root.Close()
	}
}
func filename(id string) (string, error) {
	u, err := uuid.Parse(id)
	if err != nil || u == uuid.Nil || u.String() != id {
		return "", ErrUnsafe
	}
	return id + ".jsonl", nil
}
func (d *disk) open(name string) (*os.File, error) {
	info, err := d.root.Lstat(name)
	if errors.Is(err, os.ErrNotExist) {
		return nil, ErrUnavailable
	}
	if err != nil || !info.Mode().IsRegular() {
		return nil, ErrUnsafe
	}
	f, err := d.root.Open(name)
	if err != nil {
		return nil, ErrUnavailable
	}
	if !d.validFile(name, f) {
		f.Close()
		return nil, ErrUnsafe
	}
	return f, nil
}
func parseManifest(first []byte) (Manifest, error) {
	var row line
	var record Record
	if json.Unmarshal(first, &row) != nil || row.Sequence != 1 || row.Previous != "" || row.Digest != Digest(row.Record) || json.Unmarshal(row.Record, &record) != nil || record.Manifest == nil {
		return Manifest{}, ErrUnsafe
	}
	m := *record.Manifest
	if m.Schema != SchemaVersion || m.AccountID != DedicatedAccountID || m.Admission == 0 || m.ExpiresAt.Sub(m.CreatedAt) != Retention || !m.Fingerprint.Valid() {
		return Manifest{}, ErrUnsafe
	}
	if _, err := filename(m.ID); err != nil {
		return Manifest{}, err
	}
	return m, nil
}
func (d *disk) manifest(name string) (Manifest, error) {
	f, err := d.open(name)
	if err != nil {
		return Manifest{}, err
	}
	defer f.Close()
	raw, err := bufio.NewReaderSize(f, 16<<10).ReadSlice('\n')
	if err != nil {
		return Manifest{}, ErrUnsafe
	}
	m, err := parseManifest(raw)
	if err != nil || name != m.ID+".jsonl" {
		return Manifest{}, ErrUnsafe
	}
	return m, nil
}
func (d *disk) manifests() ([]Manifest, error) {
	dir, err := d.root.Open(".")
	if err != nil {
		return nil, ErrUnsafe
	}
	entries, err := dir.ReadDir(-1)
	dir.Close()
	if err != nil {
		return nil, ErrUnsafe
	}
	var out []Manifest
	for _, entry := range entries {
		name := entry.Name()
		if name == ".lock" || name == ".owner" || name == ".blocked" {
			continue
		}
		if !strings.HasSuffix(name, ".jsonl") {
			return nil, ErrUnsafe
		}
		m, err := d.manifest(name)
		if err != nil {
			return nil, err
		}
		out = append(out, m)
	}
	return out, nil
}
func (d *disk) remove(m Manifest) error {
	name, _ := filename(m.ID)
	info, err := d.root.Lstat(name)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm() != 0600 || !owned(info) {
		return ErrCleanup
	}
	if err := d.root.Remove(name); err != nil {
		return ErrCleanup
	}
	return nil
}

func (d *disk) blocked() bool {
	_, err := d.root.Lstat(".blocked")
	return !errors.Is(err, os.ErrNotExist)
}

type View struct {
	Manifest   Manifest
	Records    []Record
	Incomplete bool
	Bytes      int
}

// Read is for one explicitly selected bundle; never creates files or extends TTL.
// Call Recheck before publishing content or replay output after expensive work.
func Read(path, id string, now time.Time) (View, error) {
	d, err := openDisk(path)
	if err != nil {
		return View{}, err
	}
	defer d.close()
	if err = d.acquire(); err != nil {
		return View{}, err
	}
	defer d.release()
	if d.blocked() {
		return View{}, ErrCleanup
	}
	name, err := filename(id)
	if err != nil {
		return View{}, err
	}
	m, err := d.manifest(name)
	if err != nil {
		return View{}, err
	}
	if !now.Before(m.ExpiresAt) || now.Before(m.CreatedAt) {
		return View{}, ErrUnavailable
	}
	f, err := d.open(name)
	if err != nil {
		return View{}, err
	}
	defer f.Close()
	raw, err := io.ReadAll(io.LimitReader(f, MaxBytes+1))
	if err != nil || len(raw) > MaxBytes {
		return View{}, ErrUnsafe
	}
	defer clear(raw)
	view := View{Manifest: m, Bytes: len(raw)}
	previous := ""
	sequence := uint64(0)
	for len(raw) > 0 {
		end := bytes.IndexByte(raw, '\n')
		if end < 0 {
			view.Incomplete = true
			break
		}
		var row line
		var record Record
		if json.Unmarshal(raw[:end], &row) != nil || row.Sequence != sequence+1 || row.Previous != previous || row.Digest != Digest(append([]byte(previous), row.Record...)) || json.Unmarshal(row.Record, &record) != nil {
			return View{}, ErrUnsafe
		}
		view.Records = append(view.Records, record)
		sequence = row.Sequence
		previous = row.Digest
		raw = raw[end+1:]
	}
	foundSummary := false
	for _, r := range view.Records {
		if r.Summary != nil {
			foundSummary = true
		}
	}
	view.Incomplete = view.Incomplete || !foundSummary
	return view, nil
}
func Recheck(path string, m Manifest, now time.Time) error {
	if !now.Before(m.ExpiresAt) || now.Before(m.CreatedAt) {
		return ErrUnavailable
	}
	d, err := openDisk(path)
	if err != nil {
		return err
	}
	defer d.close()
	if err = d.acquire(); err != nil {
		return err
	}
	defer d.release()
	if d.blocked() {
		return ErrCleanup
	}
	current, err := d.manifest(m.ID + ".jsonl")
	if err != nil || current != m {
		return ErrUnavailable
	}
	return nil
}

// Clear removes only a validated, explicitly named bundle. Writers never recreate
// an existing bundle, so clearing also revokes future asynchronous appends.
func Clear(path, id string) error {
	d, err := openDisk(path)
	if err != nil {
		return err
	}
	defer d.close()
	if err = d.acquire(); err != nil {
		return err
	}
	defer d.release()
	name, err := filename(id)
	if err != nil {
		return err
	}
	m, err := d.manifest(name)
	if err != nil {
		return err
	}
	return d.remove(m)
}

package generationevidence

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"os"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/google/uuid"
	"golang.org/x/sys/unix"
	gt "wordweave/internal/generationtrace"
)

type Options struct {
	Directory   string
	Fingerprint Fingerprint
}
type Manager struct {
	mu              sync.Mutex // admission/lifecycle IO only; never acquired by capture callbacks
	disk            *disk
	owner           *os.File
	opts            Options
	entries         map[string]*Bundle
	admission       uint64
	closed, blocked bool
	closing         atomic.Bool
	closeOnce       sync.Once
	closeDone       chan struct{}
	closeErr        error
	now             func() time.Time
	stop            chan struct{}
	done            chan struct{}
	remove          func(Manifest) error
}
type Bundle struct {
	manager                   *Manager
	manifest                  Manifest
	deadline                  time.Time // carries monotonic clock during this process
	revoked                   atomic.Bool
	mu                        sync.Mutex // bounded memory bookkeeping, no IO
	queue                     chan []byte
	wake                      chan struct{}
	done                      chan struct{}
	state                     State
	reserved, metadata, final int
	sequence                  uint64 // writer only
	previous                  string // writer only
	exact                     bool
	accepted                  uint64
	progress                  [3]*gt.Event
}

func Open(opts Options) (*Manager, error) {
	if !opts.Fingerprint.Valid() {
		return nil, ErrUnsafe
	}
	d, err := openDisk(opts.Directory)
	if err != nil {
		return nil, err
	}
	owner, err := d.root.OpenFile(".owner", os.O_CREATE|os.O_RDWR, 0600)
	if err != nil || !d.validFile(".owner", owner) {
		if owner != nil {
			owner.Close()
		}
		d.close()
		return nil, ErrUnsafe
	}
	if unix.Flock(int(owner.Fd()), unix.LOCK_EX|unix.LOCK_NB) != nil {
		owner.Close()
		d.close()
		return nil, ErrBusy
	}
	m := &Manager{disk: d, owner: owner, opts: opts, entries: make(map[string]*Bundle), now: time.Now, stop: make(chan struct{}), done: make(chan struct{}), closeDone: make(chan struct{})}
	m.remove = d.remove
	if err = m.load(); err != nil {
		owner.Close()
		d.close()
		return nil, err
	}
	go m.run()
	return m, nil
}
func (m *Manager) load() error {
	if err := m.disk.acquire(); err != nil {
		return err
	}
	defer m.disk.release()
	manifests, err := m.disk.manifests()
	if err != nil {
		return err
	}
	blocked := m.disk.blocked()
	for _, mf := range manifests {
		if mf.Admission > m.admission {
			m.admission = mf.Admission
		}
		if blocked || !m.now().Before(mf.ExpiresAt) || m.now().Before(mf.CreatedAt) {
			if err = m.remove(mf); err != nil {
				m.markBlocked()
				return ErrCleanup
			}
			continue
		}
		// Restarted bundles remain inspectable but are never resumed or rewritten.
		b := &Bundle{manager: m, manifest: mf, deadline: m.now().Add(mf.ExpiresAt.Sub(m.now())), done: make(chan struct{})}
		close(b.done)
		m.entries[mf.ID] = b
	}
	for len(m.entries) > MaxBundles {
		if err := m.evictOldest(); err != nil {
			return err
		}
	}
	if blocked {
		if err := m.disk.root.Remove(".blocked"); err != nil {
			return ErrCleanup
		}
	}
	return nil
}
func (m *Manager) run() {
	defer close(m.done)
	timer := time.NewTicker(time.Second)
	defer timer.Stop()
	for {
		select {
		case <-m.stop:
			return
		case <-timer.C:
			_ = m.Sweep()
		}
	}
}
func (m *Manager) markBlocked() {
	if !m.blocked {
		slog.Warn("generation_evidence_cleanup_failed")
	}
	m.blocked = true
	// Readers fail closed on this control marker; never include paths in errors.
	f, err := m.disk.root.OpenFile(".blocked", os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err == nil {
		_ = f.Close()
	}
}
func (m *Manager) revoke(b *Bundle) error {
	b.revoked.Store(true)
	if b.wake != nil {
		select {
		case b.wake <- struct{}{}:
		default:
		}
	}
	if err := m.remove(b.manifest); err != nil {
		m.markBlocked()
		return ErrCleanup
	}
	delete(m.entries, b.manifest.ID)
	return nil
}
func (m *Manager) evictOldest() error {
	var oldest *Bundle
	for _, b := range m.entries {
		if oldest == nil || b.manifest.Admission < oldest.manifest.Admission {
			oldest = b
		}
	}
	if oldest == nil {
		return nil
	}
	return m.revoke(oldest)
}

// Admit is after server-side identity resolution, before Start. It may do small
// private tmpfs admission IO; streaming/content callbacks never acquire this lock.
func (m *Manager) Admit(kind, accountID, requestID string, started time.Time) *Bundle {
	if m == nil || kind != "account" || accountID != DedicatedAccountID {
		return nil
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closing.Load() || m.closed || m.blocked || gt.SafeID(requestID) != requestID || requestID == "" {
		return nil
	}
	if err := m.disk.acquire(); err != nil {
		return nil
	}
	defer m.disk.release()
	now := m.now()
	if started.IsZero() || started.After(now) || !now.Before(started.Add(Retention)) {
		return nil
	}
	if len(m.entries) >= MaxBundles {
		if m.evictOldest() != nil {
			return nil
		}
	}
	m.admission++
	id := uuid.NewString()
	mf := Manifest{Schema: SchemaVersion, ID: id, AccountID: accountID, RequestID: requestID, Admission: m.admission, CreatedAt: started.UTC(), ExpiresAt: started.Add(Retention).UTC(), Fingerprint: m.opts.Fingerprint}
	data, _ := json.Marshal(Record{Manifest: &mf})
	wire := encodeLine(1, "", data)
	f, err := m.disk.root.OpenFile(id+".jsonl", os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		return nil
	}
	_, writeErr := f.Write(wire)
	closeErr := f.Close()
	if writeErr != nil || closeErr != nil {
		if m.remove(mf) != nil {
			m.markBlocked()
		}
		return nil
	}
	b := &Bundle{manager: m, manifest: mf, deadline: started.Add(Retention), queue: make(chan []byte, queueSlots), wake: make(chan struct{}, 1), done: make(chan struct{}), reserved: len(wire) + guardBudget, metadata: len(wire), sequence: 1, previous: Digest(data)}
	m.entries[id] = b
	go b.writeLoop()
	return b
}
func (b *Bundle) ID() string {
	if b == nil {
		return ""
	}
	return b.manifest.ID
}
func (b *Bundle) alive() bool {
	return b != nil && !b.manager.closing.Load() && !b.revoked.Load() && time.Now().Before(b.deadline)
}
func (b *Bundle) submit(record Record, category string) {
	if !b.alive() || b.queue == nil {
		return
	}
	// Bound allocations before encoding caller-controlled content. Model fragments
	// are small (guard-owned); an oversized valid spec only truncates diagnostics.
	if record.Chunk != nil && len(record.Chunk.Text) > 4096 {
		b.drop(uint64(len(record.Chunk.Text)), true)
		return
	}
	if record.Spec != nil {
		n := len(record.Spec.ProviderModelID)
		for _, e := range record.Spec.Entries {
			n += len(e)
		}
		if n > 8<<10 {
			b.drop(uint64(n), true)
			return
		}
	}
	body, err := json.Marshal(record)
	if err != nil {
		b.drop(0, true)
		return
	}
	// Journal wrapping uses ~190 bytes; fixed reserve safely bounds sequence/hash.
	cost := len(body) + 256
	b.mu.Lock()
	defer b.mu.Unlock()
	if !b.alive() {
		return
	}
	limit := MaxBytes - finalBudget
	if category == "final" {
		limit = MaxBytes
	}
	if b.reserved+cost > limit || category == "metadata" && b.metadata+cost > metadataBudget || category == "final" && b.final+cost > finalBudget {
		b.state.Truncated = true
		b.state.DroppedRecords++
		b.state.DroppedBytes += uint64(len(body))
		return
	}
	select {
	case b.queue <- body:
		b.accepted++
		b.reserved += cost
		if category == "metadata" {
			b.metadata += cost
		}
		if category == "final" {
			b.final += cost
		}
	default:
		b.state.DroppedRecords++
		b.state.DroppedBytes += uint64(len(body))
	}
}
func (b *Bundle) drop(n uint64, truncated bool) {
	if b == nil {
		return
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.state.DroppedRecords++
	b.state.DroppedBytes += n
	b.state.Truncated = b.state.Truncated || truncated
}
func (b *Bundle) Event(e gt.Event) {
	if !b.alive() {
		return
	}
	// Raw fragments already preserve every content byte. Keep latest repetitive
	// progress counters, without spending the metadata reserve on every token.
	slot := -1
	if e.Kind == "fact" && e.Fact.Stage == gt.ProviderStream.String() && e.Fact.Detail.Reason == "" {
		if e.Fact.Check == "frame" {
			slot = 0
		}
		if e.Fact.Check == "content" {
			slot = 1
		}
	}
	if slot >= 0 {
		b.mu.Lock()
		b.progress[slot] = &e
		b.state.CoalescedProgress++
		b.mu.Unlock()
		return
	}
	if e.Kind == "provider" && e.Fact.Stage == gt.ProviderStream.String() && e.Provider != nil {
		p := e.Provider
		if !p.ErrorPresent && !p.UsageProvided && p.FinishReason == "not_provided" && p.SyntaxOffset < 0 {
			b.mu.Lock()
			previous := b.progress[2]
			same := false
			if previous != nil {
				a, c := *previous.Provider, *p
				a.Frame, c.Frame = 0, 0
				a.Bytes, c.Bytes = 0, 0
				same = a == c
			}
			b.progress[2] = &e
			if same {
				b.state.CoalescedProgress++
			}
			b.mu.Unlock()
			if same {
				return
			}
		}
	}
	b.submit(Record{Event: &e}, "metadata")
}
func (b *Bundle) Summary(s gt.Summary) {
	if b == nil {
		return
	}
	b.mu.Lock()
	state := b.state
	var progress []gt.Event
	for _, e := range b.progress {
		if e != nil {
			progress = append(progress, *e)
		}
	}
	b.mu.Unlock()
	b.submit(Record{Summary: &s, State: &state, Progress: progress}, "final")
}
func (b *Bundle) EffectiveSpec(s gt.EffectiveSpec) {
	if b == nil {
		return
	}
	// Only called after successful Start. Defensive generic credential rejection;
	// the provider boundary is responsible for exact-key and cross-chunk filtering.
	if suspect(s.ProviderModelID) {
		b.drop(0, true)
		return
	}
	if len(s.Entries) > 1024 {
		b.drop(0, true)
		return
	}
	s.Entries = append([]string(nil), s.Entries...)
	b.submit(Record{Spec: &s}, "metadata")
}
func suspect(value string) bool {
	v := strings.ToLower(value)
	for _, prefix := range []string{"sk-", "bearer ", "authorization:", "password=", "api_key="} {
		if strings.Contains(v, prefix) {
			return true
		}
	}
	return false
}
func (b *Bundle) ModelChunk(chunk gt.ModelChunk) {
	if b == nil {
		return
	}
	if chunk.Redacted {
		b.mu.Lock()
		b.state.Redacted = true
		b.mu.Unlock()
	}
	b.submit(Record{Chunk: &chunk}, "content")
}
func (b *Bundle) ModelEnd(end gt.ModelEnd) {
	if b == nil {
		return
	}
	b.mu.Lock()
	b.state.ModelEnded = true
	b.state.Redacted = b.state.Redacted || end.Redacted
	b.state.Unavailable = b.state.Unavailable || end.Unavailable
	b.exact = !b.state.Redacted && !b.state.Unavailable
	b.mu.Unlock()
	b.submit(Record{ModelEnd: &end}, "final")
}
func (b *Bundle) Processing(p gt.Processing) {
	if b == nil || !b.ByteExact() || (p.Kind != "candidate" && p.Kind != "validated" && p.Kind != "passage_deltas") || !digestValid(p.SHA256) {
		return
	}
	b.submit(Record{Processing: &p}, "metadata")
}
func (b *Bundle) ByteExact() bool {
	if !b.alive() {
		return false
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.exact && !b.state.Truncated && b.state.DroppedRecords == 0 && !b.state.IOFailed
}
func (b *Bundle) writeLoop() {
	defer close(b.done)
	defer func() {
		for {
			select {
			case data := <-b.queue:
				clear(data)
			default:
				return
			}
		}
	}()
	for {
		select {
		case <-b.wake:
			if b.revoked.Load() {
				return
			}
		case data := <-b.queue:
			if !b.alive() {
				clear(data)
				return
			}
			b.manager.mu.Lock()
			if !b.alive() || b.manager.blocked || b.manager.closed {
				b.manager.mu.Unlock()
				clear(data)
				return
			}
			err := b.append(data)
			// An inspector holds the journal lock only briefly. Retry off the
			// streaming path; contention is not corruption or a model failure.
			retryUntil := time.Now().Add(time.Second)
			for errors.Is(err, ErrBusy) && b.alive() && time.Now().Before(retryUntil) {
				timer := time.NewTimer(5 * time.Millisecond)
				select {
				case <-timer.C:
				case <-b.wake:
				}
				timer.Stop()
				if !b.alive() {
					break
				}
				err = b.append(data)
			}
			b.manager.mu.Unlock()
			clear(data)
			if err != nil {
				slog.Warn("generation_evidence_write_failed")
				b.mu.Lock()
				b.state.IOFailed = true
				b.mu.Unlock()
				b.revoked.Store(true)
				return
			}
		}
	}
}
func (b *Bundle) append(data []byte) error {
	d := b.manager.disk
	if err := d.acquire(); err != nil {
		return err
	}
	defer d.release()
	name := b.manifest.ID + ".jsonl"
	f, err := d.root.OpenFile(name, os.O_WRONLY|os.O_APPEND, 0600)
	if err != nil {
		return ErrUnavailable
	}
	defer f.Close()
	if !d.validFile(name, f) {
		return ErrUnsafe
	}
	info, err := f.Stat()
	if err != nil {
		return ErrUnsafe
	}
	wire := encodeLine(b.sequence+1, b.previous, data)
	if info.Size()+int64(len(wire)) > MaxBytes {
		return ErrUnsafe
	}
	if !b.alive() {
		return ErrUnavailable
	}
	if _, err = f.Write(wire); err != nil {
		return ErrUnavailable
	}
	b.sequence++
	b.previous = Digest(append([]byte(b.previous), data...))
	return nil
}
func (m *Manager) Sweep() error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed || m.closing.Load() {
		return nil
	}
	if err := m.disk.acquire(); err != nil {
		return err
	}
	defer m.disk.release()
	for _, b := range m.entries {
		if b.revoked.Load() || !m.now().Before(b.deadline) {
			if err := m.revoke(b); err != nil {
				return err
			}
		}
	}
	if m.blocked {
		if err := m.disk.root.Remove(".blocked"); err != nil && !errors.Is(err, os.ErrNotExist) {
			return ErrCleanup
		}
		m.blocked = false
	}
	return nil
}
func (m *Manager) RevokeAccount(accountID string) error {
	if m == nil || accountID != DedicatedAccountID {
		return nil
	}
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()
	return m.Close(ctx)
}
func (m *Manager) Close(ctx context.Context) error {
	if m == nil {
		return nil
	}
	// Revoke callbacks immediately, even while filesystem IO is stalled.
	m.closeOnce.Do(func() { m.closing.Store(true); go m.close() })
	select {
	case <-m.closeDone:
		return m.closeErr
	case <-ctx.Done():
		return ErrCleanup
	}
}
func (m *Manager) close() {
	defer close(m.closeDone)
	m.mu.Lock()
	m.closed = true
	close(m.stop)
	var workers []*Bundle
	for _, b := range m.entries {
		b.revoked.Store(true)
		if b.wake != nil {
			select {
			case b.wake <- struct{}{}:
			default:
			}
		}
		workers = append(workers, b)
	}
	err := m.disk.acquire()
	if err == nil {
		for _, b := range workers {
			if e := m.remove(b.manifest); e != nil {
				err = e
				m.markBlocked()
			} else {
				delete(m.entries, b.manifest.ID)
			}
		}
		m.disk.release()
	} else {
		m.markBlocked()
	}
	m.mu.Unlock()
	// The caller has a bounded wait; cleanup remains revoked if IO takes longer.
	for _, b := range workers {
		<-b.done
	}
	<-m.done
	m.mu.Lock()
	m.owner.Close()
	m.disk.close()
	m.mu.Unlock()
	m.closeErr = err
}
func (m *Manager) IDs() []string {
	m.mu.Lock()
	defer m.mu.Unlock()
	out := make([]string, 0, len(m.entries))
	for id := range m.entries {
		out = append(out, id)
	}
	sort.Strings(out)
	return out
}

package generationevidence

