		t.Fatal("capacity")
	}
	last := admit(t, m)
	if len(m.IDs()) != 50 || last.ID() == first.ID() {
		t.Fatal("rotation")
	}
	first.ModelChunk(gt.ModelChunk{Index: 1, OriginalBytes: 4, Text: "late"})
	select {
	case <-first.done:
	case <-time.After(time.Second):
		t.Fatal("revoked worker alive")
