					t.Fatal(err)
				}
			case "partial_tail":
				f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0600)
				if err != nil {
					t.Fatal(err)
				}
				f.WriteString("{")
				f.Close()
				v, err := Read(p, b.ID(), time.Now())
				if err != nil || !v.Incomplete {
					t.Fatal("partial tail accepted as complete", err)
				}
			}
		})
	}
}
func TestOBS042BAccountDeletionAndPersistentCloseError(t *testing.T) {
	m, p := testManager(t)
	b := admit(t, m)
	if err := m.RevokeAccount("different-account"); err != nil || !b.alive() {
		t.Fatal("other account revoked")
	}
	if err := m.RevokeAccount(DedicatedAccountID); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(filepath.Join(p, b.ID()+".jsonl")); !errors.Is(err, os.ErrNotExist) {
		t.Fatal("account evidence remains")
	}
	if m.Admit("account", DedicatedAccountID, "req_after_delete", time.Now()) != nil {
		t.Fatal("deleted account readmitted")
	}
}
func TestOBS042BRecoveryCleansBlockedAndExpiredWithoutTTLReset(t *testing.T) {
	p := privateDirectory(t)
	now := time.Now()
	var ids []string
	for i := 0; i < 2; i++ {
		id := fmt.Sprintf("00000000-0000-4000-8000-%012d", i+1)
		ids = append(ids, id)
		start := now.Add(-time.Hour)
		if i == 0 {
			start = now.Add(-25 * time.Hour)
		}
		mf := Manifest{Schema: 1, ID: id, AccountID: DedicatedAccountID, RequestID: "req_restart", Admission: uint64(i + 1), CreatedAt: start, ExpiresAt: start.Add(Retention), Fingerprint: testFingerprint()}
		raw, _ := json.Marshal(Record{Manifest: &mf})
		if err := os.WriteFile(filepath.Join(p, id+".jsonl"), encodeLine(1, "", raw), 0600); err != nil {
			t.Fatal(err)
		}
	}
	m, err := Open(Options{p, testFingerprint()})
	if err != nil {
		t.Fatal(err)
	}
	if len(m.IDs()) != 1 {
		t.Fatal("expired survived startup")
	}
	v, err := Read(p, ids[1], time.Now())
	if err != nil || !v.Incomplete || !v.Manifest.CreatedAt.Equal(now.Add(-time.Hour)) {
		t.Fatal("restart changed provenance or TTL", err)
	}
	// Simulate a crash: no Close cleanup, no active writers in these fixtures.
	close(m.stop)
	<-m.done
	m.owner.Close()
	m.disk.close()
	if err = os.WriteFile(filepath.Join(p, ".blocked"), nil, 0600); err != nil {
		t.Fatal(err)
	}
	m, err = Open(Options{p, testFingerprint()})
	if err != nil {
		t.Fatal(err)
	}
	if len(m.IDs()) != 0 {
		t.Fatal("blocked recovery exposed old data")
	}
	if err = m.Close(context.Background()); err != nil {
		t.Fatal(err)
	}
}

package generationevidence

import (
	"time"
	"unicode/utf8"

	gt "wordweave/internal/generationtrace"
)

// Material is private and ephemeral. It is neither a normal log DTO nor an
// export format. A command must Recheck the manifest immediately before output.
type Material struct {
	Spec       gt.EffectiveSpec
	Chunks     []string
	Summary    gt.Summary
	Processing map[string]string
}

// Reconstruct requires every original delta, with its exact byte boundary.
// A missing record is not repaired, inferred or accepted as a successful replay.
func Reconstruct(view View, current Fingerprint, now time.Time) (Material, string) {
	if !current.Valid() || view.Manifest.Fingerprint != current {
		return Material{}, "fingerprint_mismatch"
	}
	if !now.Before(view.Manifest.ExpiresAt) || now.Before(view.Manifest.CreatedAt) {
		return Material{}, "expired"
	}
	if view.Incomplete {
		return Material{}, "incomplete_journal"
	}
	m := Material{Processing: make(map[string]string)}
	var end *gt.ModelEnd
	specs, summaries := 0, 0
	total := int64(0)
	var index uint64
	originalBytes := 0
	currentText := ""
	for _, r := range view.Records {
		if r.State != nil && (r.State.Truncated || r.State.DroppedRecords > 0 || r.State.IOFailed || r.State.Redacted || r.State.Unavailable) {
			return Material{}, "capture_not_exact"
		}
		if r.Spec != nil {
			specs++
			m.Spec = *r.Spec
		}
		if r.Summary != nil {
			summaries++
			m.Summary = *r.Summary
		}
		if r.Processing != nil {
			p := r.Processing
			if (p.Kind != "candidate" && p.Kind != "validated" && p.Kind != "passage_deltas") || !digestValid(p.SHA256) || m.Processing[p.Kind] != "" {
				return Material{}, "invalid_processing"
			}
			m.Processing[p.Kind] = p.SHA256
		}
		if r.ModelEnd != nil {
			if end != nil || r.ModelEnd.Redacted || r.ModelEnd.Unavailable {
				return Material{}, "capture_not_exact"
			}
			end = r.ModelEnd
		}
		if r.Chunk == nil {
			continue
		}
		c := r.Chunk
		if c.Redacted {
			return Material{}, "capture_not_exact"
		}
		if end != nil || c.Index == 0 || c.OriginalBytes <= 0 || c.OriginalBytes > MaxBytes || len(c.Text) == 0 || !utf8.ValidString(c.Text) {
			return Material{}, "invalid_chunk"
		}
		if c.Index != index {
			if c.Index != index+1 || len(currentText) != originalBytes {
				return Material{}, "missing_chunk"
			}
			if index > 0 {
				m.Chunks = append(m.Chunks, currentText)
			}
			index = c.Index
			originalBytes = c.OriginalBytes
			currentText = ""
		}
		if c.OriginalBytes != originalBytes || c.Offset != len(currentText) || len(currentText)+len(c.Text) > originalBytes {
			return Material{}, "invalid_offset"
		}
		total += int64(len(c.Text))
		if total > MaxBytes {
			return Material{}, "capture_not_exact"
		}
		currentText += c.Text
	}
	if end == nil || end.Chunks != index || end.Bytes != total || len(currentText) != originalBytes {
		return Material{}, "missing_model_end_or_content"
	}
	if index > 0 {
		m.Chunks = append(m.Chunks, currentText)
	}
	if specs != 1 || summaries != 1 {
		return Material{}, "missing_spec_or_summary"
	}
	m.Spec.Entries = append([]string(nil), m.Spec.Entries...)
	return m, ""
}

// Package generationevidence owns private, short-lived local diagnostic files.
// It has no database, HTTP, model client or authentication dependency.
package generationevidence

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"time"

	gt "wordweave/internal/generationtrace"
)

const (
	SchemaVersion      = 1
	DedicatedAccountID = "01a08e5a-2250-7854-81df-5aeb26e7f461"
	MaxBundles         = 50
	MaxBytes           = 1 << 20
	Retention          = 24 * time.Hour
	metadataBudget     = 128 << 10
	finalBudget        = 16 << 10
	guardBudget        = 64 << 10
	queueSlots         = 256
)

var (
	ErrUnavailable = errors.New("diagnostic evidence unavailable")
	ErrUnsafe      = errors.New("invalid private diagnostic storage")
	ErrCleanup     = errors.New("diagnostic cleanup failed; access disabled")
	ErrBusy        = errors.New("diagnostic storage busy")
)

type Fingerprint struct {
	Source    string `json:"source_sha256"`
	Binary    string `json:"binary_sha256"`
	Template  string `json:"template_sha256"`
	Schema    string `json:"schema_sha256"`
	Validator string `json:"validator_sha256"`
	Lexicon   string `json:"lexicon_sha256"`
}

func (f Fingerprint) Valid() bool {
	for _, v := range []string{f.Source, f.Binary, f.Template, f.Schema, f.Validator, f.Lexicon} {
		if !digestValid(v) {
			return false
		}
	}
	return true
}
func digestValid(s string) bool {
	b, err := hex.DecodeString(s)
	return err == nil && len(b) == sha256.Size && hex.EncodeToString(b) == s
}
func Digest(raw []byte) string { sum := sha256.Sum256(raw); return hex.EncodeToString(sum[:]) }

type Manifest struct {
	Schema      int         `json:"schema"`
	ID          string      `json:"evidence_id"`
	AccountID   string      `json:"account_id"`
	RequestID   string      `json:"request_id"`
	Admission   uint64      `json:"admission"`
	CreatedAt   time.Time   `json:"created_at"`
	ExpiresAt   time.Time   `json:"expires_at"`
	Fingerprint Fingerprint `json:"fingerprint"`
}
type State struct {
	CoalescedProgress uint64 `json:"coalesced_progress"`
	DroppedRecords    uint64 `json:"dropped_records"`
	DroppedBytes      uint64 `json:"dropped_bytes"`
	Truncated         bool   `json:"truncated"`
	IOFailed          bool   `json:"io_failed"`
	Redacted          bool   `json:"redacted"`
	ModelEnded        bool   `json:"model_ended"`
	Unavailable       bool   `json:"unavailable"`
}

// Record is an allowlist; it is not a general JSON logging or object dump API.
type Record struct {
	Manifest   *Manifest         `json:"manifest,omitempty"`
	Spec       *gt.EffectiveSpec `json:"spec,omitempty"`
	Chunk      *gt.ModelChunk    `json:"chunk,omitempty"`
	ModelEnd   *gt.ModelEnd      `json:"model_end,omitempty"`
	Event      *gt.Event         `json:"event,omitempty"`
	Summary    *gt.Summary       `json:"summary,omitempty"`
	Processing *gt.Processing    `json:"processing,omitempty"`
	State      *State            `json:"capture_state,omitempty"`
	Progress   []gt.Event        `json:"latest_progress,omitempty"`
}

// Hash chained journal detects corruption, reordering and partial tails. It is
// not a signature against an operator who already controls the private UID.
type line struct {
	Sequence uint64          `json:"sequence"`
	Previous string          `json:"previous"`
	Digest   string          `json:"sha256"`
	Record   json.RawMessage `json:"record"`
}

func encodeLine(sequence uint64, previous string, body []byte) []byte {
	digest := Digest(append([]byte(previous), body...))
	raw, _ := json.Marshal(line{sequence, previous, digest, body})
	return append(raw, '\n')
}

package generationtrace

// Capture is a distinct, private-only channel. Implementations must be bounded,
// revokeable, and return immediately from callbacks without performing file IO.
// Nothing supplied here may be forwarded to the normal telemetry Sink.
type Capture interface {
	Sink
	EffectiveSpec(EffectiveSpec)
	ModelChunk(ModelChunk)
	ModelEnd(ModelEnd)
	Processing(Processing)
	ByteExact() bool
}

type EffectiveSpec struct {
	RunID           string   `json:"run_id"`
	ModelID         string   `json:"model_id"`
	ProviderModelID string   `json:"provider_model_id"`
	MeaningLanguage string   `json:"meaning_language"`
	Scenario        string   `json:"scenario"`
	LengthCode      string   `json:"length"`
	MinimumWords    int      `json:"minimum_words"`
	Entries         []string `json:"entries"`
	PromptVersion   string   `json:"prompt_version"`
}

// Fragments retain the original delta.content boundary even when redaction
// buffering splits a chunk. Offsets and OriginalBytes refer to that delta only.
type ModelChunk struct {
	Index         uint64 `json:"index"`
	Offset        int    `json:"offset"`
	OriginalBytes int    `json:"original_bytes"`
	Text          string `json:"text"`
	Redacted      bool   `json:"redacted"`
}
type ModelEnd struct {
	Chunks      uint64 `json:"chunks"`
	Bytes       int64  `json:"bytes"`
	Redacted    bool   `json:"redacted"`
	Unavailable bool   `json:"unavailable"`
}

// Digests refer to deterministic materializations of captured model_text, not
// to credentials. They are emitted only after byte-exact model capture ends.
type Processing struct {
	Kind   string `json:"kind"` // candidate, validated or passage_deltas
	SHA256 string `json:"sha256"`
}

func (t *Trace) AttachCapture(capture Capture) {
	if t == nil || capture == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.capture != nil || t.finished {
		return
	}
	t.capture = capture
	// The early request start preceded identity verification. Supply its actual
	// state now without persisting any unverified identity or request payload.
	capture.Event(Event{RequestID: t.requestID, Kind: "capture_attached", Fact: t.stages[Request]})
}
func (t *Trace) Capture() Capture {
	if t == nil {
		return nil
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.capture
}

package generationtrace

// ProviderFact is a separate allowlisted projection, never an upstream envelope.
// Usage numbers are latest cumulative totals (not sums of repeated usage frames).
type ProviderFact struct {
	ID               string `json:"id"`
	RequestID        string `json:"upstream_request_id"`
	HTTPStatus       int    `json:"http_status"`
	Frame            int64  `json:"frame"`
	Bytes            int64  `json:"bytes"`
	Choice           int    `json:"choice_index"`
	ChoiceProvided   bool   `json:"choice_index_provided"`
	FinishReason     string `json:"finish_reason"`
	ErrorPresent     bool   `json:"error_present"`
	ErrorCodeType    string `json:"error_code_type"`
	ErrorCode        int    `json:"error_code"`
	UsageProvided    bool   `json:"usage_provided"`
	PromptTokens     int64  `json:"prompt_tokens"`
	CompletionTokens int64  `json:"completion_tokens"`
	TotalTokens      int64  `json:"total_tokens"`
	SyntaxOffset     int64  `json:"syntax_offset"`
}

func (t *Trace) Provider(s Stage, fact ProviderFact) {
	if t == nil || s >= stageCount {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	fact.ID, fact.RequestID = SafeID(fact.ID), SafeID(fact.RequestID)
	fact.FinishReason = member(fact.FinishReason, "stop|length|tool_calls|function_call|content_filter|error|not_provided", "other")
	if fact.FinishReason == "" {
		fact.FinishReason = "not_provided"
	}
	fact.ErrorCodeType = member(fact.ErrorCodeType, "number|string|null|other|not_provided", "other")
	if fact.ErrorCodeType == "" {
		fact.ErrorCodeType = "not_provided"
	}
	if fact.ErrorCode < 100 || fact.ErrorCode > 599 {
		fact.ErrorCode = 0
	}
	if fact.HTTPStatus < 100 || fact.HTTPStatus > 599 {
		fact.HTTPStatus = 0
	}
	t.emitLocked(Event{Kind: "provider", Fact: t.stages[s], Provider: &fact})
}

// Package generationtrace carries content-free generation facts across layers.
// It deliberately cannot accept errors, arbitrary maps, prompts or model text.
package generationtrace

import (
	"context"
	"strings"
	"sync"
	"time"
)

type Stage uint8

const (
	Request Stage = iota
	Preflight
	ProviderOpen
	ProviderStream
	PassageDecode
	CandidateDecode
	ContentValidate
	DraftCommit
	Settlement
	Delivery
	stageCount
)

var stageNames = [...]string{"request", "preflight", "provider_open", "provider_stream", "passage_decode", "candidate_decode", "content_validate", "draft_commit", "settlement", "delivery"}

func (s Stage) String() string {
	if s >= stageCount {
		return "unknown"
	}
	return stageNames[s]
}

type State string

const (
	NotRun     State = "not_run"
	Running    State = "running"
	OK         State = "ok"
	Failed     State = "failed"
	Cancelled  State = "cancelled"
	Incomplete State = "incomplete"
)

// Detail is sanitized again at the boundary, even for internal callers.
// -1 means unknown; offsets are model-content bytes, never guessed positions.
type Detail struct {
	Reason       string `json:"reason"`
	Field        string `json:"field"`
	Target       int    `json:"target_index"`
	Actual       int    `json:"actual"`
	Limit        int    `json:"limit"`
	Start        int64  `json:"byte_start"`
	End          int64  `json:"byte_end"`
	ExpectedType string `json:"expected_type"`
	ActualType   string `json:"actual_type"`
}

func Why(reason string) Detail {
	return Detail{Reason: reason, Target: -1, Actual: -1, Limit: -1, Start: -1, End: -1}
}

type StageFact struct {
	Stage      string `json:"stage"`
	State      State  `json:"state"`
	BeginMS    int64  `json:"begin_ms"`
	EndMS      int64  `json:"end_ms"`
	DurationMS int64  `json:"duration_ms"`
	Check      string `json:"check"`
	Detail     Detail `json:"detail"`
}
type Event struct {
	RequestID string        `json:"request_id"`
	RunID     string        `json:"run_id"`
	ModelID   string        `json:"model_id"`
	Sequence  uint64        `json:"sequence"`
	ElapsedMS int64         `json:"elapsed_ms"`
	Kind      string        `json:"kind"`
	Late      bool          `json:"after_http_finish"`
	Fact      StageFact     `json:"fact"`
	Provider  *ProviderFact `json:"provider,omitempty"`
	Outcome   string        `json:"outcome,omitempty"`
	Refunded  bool          `json:"quota_refunded"`
}
type Summary struct {
	RequestID    string                `json:"request_id"`
	RunID        string                `json:"run_id"`
	ModelID      string                `json:"model_id"`
	ElapsedMS    int64                 `json:"elapsed_ms"`
	Stages       [stageCount]StageFact `json:"stages"`
	FirstFailure *StageFact            `json:"first_failure,omitempty"`
	Outcome      string                `json:"confirmed_outcome"`
	Refunded     bool                  `json:"quota_refunded"`
	Pending      bool                  `json:"settlement_pending"`
}

// Sink must be bounded and must not call back into its Trace. Events are values
// with no references to caller data. Private capture must enqueue bounded work,
// never perform file IO on this path. Normal telemetry follows the server logger.
type Sink interface {
	Event(Event)
	Summary(Summary)
}

type Trace struct {
	mu                          sync.Mutex
	sink                        Sink
	capture                     Capture
	started                     time.Time
	sequence                    uint64
	finished                    bool
	requestID, runID, modelID   string
	stages                      [stageCount]StageFact
	first                       *StageFact
	outcome                     string
	refunded                    bool
	pending                     bool
	firstProvider, firstBrowser bool
}
type contextKey struct{}

func With(ctx context.Context, trace *Trace) context.Context {
	return context.WithValue(ctx, contextKey{}, trace)
}
func From(ctx context.Context) *Trace { trace, _ := ctx.Value(contextKey{}).(*Trace); return trace }
func New(requestID string, sink Sink) *Trace {
	t := &Trace{sink: sink, started: time.Now(), requestID: SafeID(requestID), outcome: "unknown"}
	for i := Stage(0); i < stageCount; i++ {
		t.stages[i] = StageFact{Stage: i.String(), State: NotRun, BeginMS: -1, EndMS: -1, DurationMS: -1, Detail: Why("")}
	}
	return t
}
func (t *Trace) BindRun(runID, modelID string) {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.runID != "" || t.finished {
		return
	}
	t.runID, t.modelID = SafeID(runID), SafeID(modelID)
	t.emitLocked(Event{Kind: "run_bound"})
}
func (t *Trace) emitLocked(e Event) {
	t.sequence++
	e.Sequence = t.sequence
	e.RequestID, e.RunID, e.ModelID = t.requestID, t.runID, t.modelID
	e.ElapsedMS, e.Late = time.Since(t.started).Milliseconds(), t.finished
	if t.sink != nil {
		t.sink.Event(e)
	}
	if t.capture != nil {
		t.capture.Event(e)
	}
}
func (t *Trace) beginLocked(s Stage) {
	f := &t.stages[s]
	if f.State != NotRun {
		return
	}
	f.State, f.BeginMS = Running, time.Since(t.started).Milliseconds()
	t.emitLocked(Event{Kind: "stage_begin", Fact: *f})
}
func (t *Trace) Begin(s Stage) {
	if t == nil || s >= stageCount {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	t.beginLocked(s)
}

// Check starts the next actually executed check and completes the previous one.
// The final check is closed by End; unexecuted checks are never manufactured.
func (t *Trace) Check(s Stage, check string, target int) {
	if t == nil || s >= stageCount {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	t.beginLocked(s)
	f := &t.stages[s]
	if f.State != Running {
		return
	}
	if f.Check != "" {
		previous := *f
		previous.State = OK
		t.emitLocked(Event{Kind: "check_end", Fact: previous})
	}
	f.Check, f.Detail = safeCheck(check), Why("")
	f.Detail.Target = target
	t.emitLocked(Event{Kind: "check_begin", Fact: *f})
}
func (t *Trace) Note(s Stage, check string, detail Detail) {
	if t == nil || s >= stageCount {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	f := t.stages[s]
	f.Check, f.Detail = safeCheck(check), sanitize(detail)
	if s == ProviderStream && f.Check == "content" && !t.firstProvider {
		t.firstProvider = true
		t.emitLocked(Event{Kind: "first_provider_content", Fact: f})
	}
	if s == Delivery && f.Check == "delta" && f.Detail.Reason == "" && !t.firstBrowser {
		t.firstBrowser = true
		t.emitLocked(Event{Kind: "first_browser_content", Fact: f})
	}
	t.emitLocked(Event{Kind: "fact", Fact: f})
}
func (t *Trace) End(s Stage, state State, detail Detail) {
	if t == nil || s >= stageCount {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	t.beginLocked(s)
	f := &t.stages[s]
	if f.State != Running {
		return
	}
	if state != OK && state != Failed && state != Cancelled && state != Incomplete {
		state = Incomplete
	}
	f.State, f.Detail = state, sanitize(detail)
	f.EndMS = time.Since(t.started).Milliseconds()
	f.DurationMS = f.EndMS - f.BeginMS
	if f.Check != "" {
		t.emitLocked(Event{Kind: "check_end", Fact: *f})
	}
	if t.first == nil && (state == Failed || state == Cancelled) {
		copy := *f
		t.first = &copy
	}
	t.emitLocked(Event{Kind: "stage_end", Fact: *f})
}

// Settlement records every attempt, but emits a confirmed outcome only once.
// The caller MUST have confirmed the persisted row before passing a terminal.
func (t *Trace) Settled(outcome string, refunded bool) {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	switch outcome {
	case "valid", "failed", "cancelled", "gone", "pending":
	default:
		outcome = "unknown"
	}
	e := Event{Kind: "settlement", Outcome: outcome, Refunded: refunded && outcome == "failed"}
	if outcome == "pending" && t.outcome == "unknown" {
		t.pending = true
	}
	t.emitLocked(e)
	t.confirmLocked(outcome, e.Refunded)
}
func (t *Trace) Confirm(outcome string, refunded bool) {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	t.confirmLocked(outcome, refunded)
}
func (t *Trace) confirmLocked(outcome string, refunded bool) {
	if t.outcome != "unknown" {
		return
	}
	switch outcome {
	case "valid", "failed", "cancelled", "gone":
	default:
		return
	}
	t.outcome, t.refunded = outcome, refunded && outcome == "failed"
	t.emitLocked(Event{Kind: "outcome_confirmed", Outcome: t.outcome, Refunded: t.refunded})
	if t.pending {
		t.pending = false
		t.emitLocked(Event{Kind: "settlement_recovered", Outcome: t.outcome, Refunded: t.refunded})
	}
}
func (t *Trace) Finish() {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.finished {
		return
	}
	t.finished = true
	s := Summary{RequestID: t.requestID, RunID: t.runID, ModelID: t.modelID, ElapsedMS: time.Since(t.started).Milliseconds(), Stages: t.stages, Outcome: t.outcome, Refunded: t.refunded}
	s.Pending = t.pending
	if t.first != nil {
		copy := *t.first
		s.FirstFailure = &copy
	}
	// Snapshot only: a still-running provider may later report its actual exit.
	for i := range s.Stages {
		if s.Stages[i].State == Running {
			s.Stages[i].State = Incomplete
		}
	}
	if t.sink != nil {
		t.sink.Summary(s)
	}
	if t.capture != nil {
		t.capture.Summary(s)
	}
}

// SafeID accepts only bounded opaque correlation IDs, not free-form headers.
func SafeID(value string) string {
	if value == "" {
		return ""
	}
	if len(value) > 128 {
		return "invalid"
	}
	if strings.HasPrefix(strings.ToLower(value), "sk-") {
		return "invalid"
	}
	for _, c := range value {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '-' || c == '_') {
			return "invalid"
		}
	}
	return value
}
func member(value, vocabulary string, fallback string) string {
	if value == "" {
		return ""
	}
	if strings.Contains("|"+vocabulary+"|", "|"+value+"|") && !strings.Contains(value, "|") {
		return value
	}
	return fallback
}
func sanitize(d Detail) Detail {
	d.Reason = member(d.Reason, reasons+"|authentication|authorization|rate_limited|protocol_error|schema_error|content_invalid", "unknown_internal")
	d.Field = member(d.Field, "passage|tags|targets|source_entry|entry_meaning|hint_phrase", "unknown")
	d.ExpectedType = member(d.ExpectedType, "string|number|boolean|array|object|null", "unknown")
	d.ActualType = member(d.ActualType, "string|number|boolean|array|object|null", "unknown")
	return d
}
func safeCheck(value string) string { return member(value, checks+"|receiver_exit", "unknown") }

const checks = "identity|origin|csrf|content_type|body|input|credentials|transaction_begin|actor_lock|group_policy|model_assignment|length_assignment|vocabulary|quota|reserve|entries|token|transaction_commit|transaction_rollback|request_encode|request_create|request_send|response_headers|frame|content|termination|extract|clean_consistency|json_schema|lexicon|context|passage_annotations|passage_ownership|passage_content|word_count|passage_language|tag_count|tag_content|tag_duplicate|target_count|passage_index|source_entry|meaning_content|meaning_repeated|hint_annotations|hint_ownership|hint_content|passage_annotation_presence|hint_annotation_presence|hint_index|hint_scan|passage_scan|passage_relations|hint_relations|passage_presence|hint_presence|collision|snapshot|draft_encode|cas|draft_insert|confirm|started|delta|heartbeat|validated|failed|cancelled|request_exit"

