package ai

import "context"

// AnnotationSourceDiagnostic is a private, explicit UAT-only projection. Never
// attach it to validation errors, public responses or ordinary log records.
type AnnotationSourceDiagnostic struct {
	SourceLabel  string `json:"source_label"`
	AdjacentWord string `json:"adjacent_word"`
}

// InspectUnknownAnnotation returns only the first source that the production
// parser cannot assign to the supplied entries. It does not repair or validate
// content and cannot expose the passage, other targets or hint/meaning fields.
func InspectUnknownAnnotation(ctx context.Context, passage string, entries []string) (AnnotationSourceDiagnostic, bool) {
	clean, annotations, err := parseAnnotatedText(ctx, passage)
	if err != nil {
		return AnnotationSourceDiagnostic{}, false
	}
	known := make(map[string]bool, len(entries))
	for _, entry := range entries {
		known[entry] = true
	}
	runes := []rune(clean)
	for _, annotation := range annotations {
		if ctx.Err() != nil {
			return AnnotationSourceDiagnostic{}, false
		}
		if known[annotation.Source] {
			continue
		}
		end := annotation.End
		if end < 1 || end > len(runes) {
			return AnnotationSourceDiagnostic{}, false
		}
		start := end
		for start > 0 && wordRune(runes[start-1]) && end-start <= 128 {
			start--
		}
		if start == end || end-start > 128 {
			return AnnotationSourceDiagnostic{}, false
		}
		return AnnotationSourceDiagnostic{annotation.Source, string(runes[start:end])}, true
	}
	return AnnotationSourceDiagnostic{}, false
}

