func TestPassageExtractorEmitsOnlyStableDecodedDeltas(t *testing.T) {
	t.Parallel()
	extractor := passageExtractor{}
	documents := []string{
		`{"passage":"Hello`,
		`{"passage":"Hello\nworld`,
		`{"passage":"Hello\nworld","tags":[]}`,
	}
	var got strings.Builder
	for _, document := range documents {
