// Deterministic paced fixture isolates replay correctness from the separate
// deliberate queue-overflow tests. There is no HTTP or model call.
type pacedReplayReader struct {
	frames []string
	offset int
}

func (r *pacedReplayReader) Read(p []byte) (int, error) {
	if len(r.frames) == 0 {
		return 0, io.EOF
	}
	if r.offset == 0 {
		time.Sleep(time.Millisecond)
	}
	n := copy(p, r.frames[0][r.offset:])
	r.offset += n
	if r.offset == len(r.frames[0]) {
		r.frames = r.frames[1:]
		r.offset = 0
	}
	return n, nil
}
func captureFixture(t *testing.T, spec GenerationSpec, text string, key string) (evidence.View, evidence.Fingerprint) {
	t.Helper()
	dir, err := filepath.EvalSymlinks(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	if err = os.Chmod(dir, 0700); err != nil {
		t.Fatal(err)
	}
	h := evidence.Digest([]byte("synthetic replay test fingerprints"))
	fp := evidence.Fingerprint{Source: h, Binary: h, Template: h, Schema: h, Validator: h, Lexicon: h}
	m, err := evidence.Open(evidence.Options{Directory: dir, Fingerprint: fp})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		if err := m.Close(ctx); err != nil {
			t.Error(err)
		}
	})
	bundle := m.Admit("account", evidence.DedicatedAccountID, "req_replay_fixture", time.Now())
	if bundle == nil {
		t.Fatal("no bundle")
	}
	trace := gt.New("req_replay_fixture", nil)
	trace.AttachCapture(bundle)
	ctx := gt.With(context.Background(), trace)
	spec.PromptVersion = PromptVersion
	bundle.EffectiveSpec(gt.EffectiveSpec{RunID: spec.RunID, ModelID: spec.ModelID, ProviderModelID: spec.ProviderModelID, MeaningLanguage: spec.MeaningLanguage, Scenario: spec.Scenario, LengthCode: spec.LengthCode, MinimumWords: spec.MinimumWords, Entries: spec.Entries, PromptVersion: spec.PromptVersion})
	var wire strings.Builder
	for start := 0; start < len(text); {
		end := min(start+17, len(text))
		for end < len(text) && !utf8.RuneStart(text[end]) {
			end--
		}
		wire.WriteString(p0SSE(text[start:end]))
		start = end
	}
	wire.WriteString("data: [DONE]\n\n")
	frames := strings.SplitAfter(wire.String(), "\n\n")
	frames = frames[:len(frames)-1]
	stream := openRouterStream{&privateProviderBody{io.NopCloser(&pacedReplayReader{frames: frames}), key}}
	candidate, err := stream.Receive(ctx, func(string) error { return nil })
	stream.Close()
	if err == nil {
		_, _ = testValidator(t).Validate(ctx, spec, candidate)
	}
	trace.Finish()
	until := time.Now().Add(3 * time.Second)
	for time.Now().Before(until) {
		view, e := evidence.Read(dir, bundle.ID(), time.Now())
		if e == nil && !view.Incomplete {
			if err := evidence.Recheck(dir, view.Manifest, time.Now()); err != nil {
				t.Fatal(err)
			}
			return view, fp
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatal("capture not complete")
	return evidence.View{}, fp
}
func cloneView(t *testing.T, v evidence.View) evidence.View {
	t.Helper()
	raw, _ := json.Marshal(v)
	var copy evidence.View
	if err := json.Unmarshal(raw, &copy); err != nil {
		t.Fatal(err)
	}
	return copy
}
func TestOBS042BReplayProductionRuleMatrix(t *testing.T) {
	validator := testValidator(t)
	cases := append([]p0ValidationCase{{name: "valid", mutate: func(*GenerationSpec, *Candidate) {}}}, p0ValidationCases()...)
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			spec, candidate := p0Candidate()
			tc.mutate(&spec, &candidate)
			view, fp := captureFixture(t, spec, p0JSON(candidate), "synthetic-key")
			var original *gt.StageFact
			for _, r := range view.Records {
				if r.Summary != nil {
					original = r.Summary.FirstFailure
				}
			}
			for _, mode := range []ReplayMode{ReplayStream, ReplayModel} {
				report := ReplayEvidence(context.Background(), view, fp, mode, validator)
				if mode == ReplayModel && original != nil && original.Stage == gt.PassageDecode.String() {
					if report.Status != "unavailable" || report.Reason != "stream_boundary_requires_stream_mode" {
						t.Fatalf("wrong scope: %+v", report)
					}
					continue
				}
				if report.Status != "reproduced" {
					for _, record := range view.Records {
						if record.State != nil {
							t.Logf("capture state: %+v; file bytes: %d", *record.State, view.Bytes)
						}
					}
					t.Fatalf("%s replay failed: %+v; original %+v", mode, report, original)
				}
				if report.Scope != "model_pipeline" {
					t.Fatal("claims full request replay")
				}
			}
		})
	}
}
func TestOBS042BReplayRejectsMissingRedactedOrChangedEvidence(t *testing.T) {
	spec, candidate := p0Candidate()
	base, fp := captureFixture(t, spec, p0JSON(candidate), "synthetic-key")
	validator := testValidator(t)
	cases := []struct {
		name           string
		mutate         func(*evidence.View, *evidence.Fingerprint)
		status, reason string
	}{
		{"fingerprint", func(v *evidence.View, f *evidence.Fingerprint) { f.Source = evidence.Digest([]byte("changed source")) }, "unavailable", "fingerprint_mismatch"},
		{"expired", func(v *evidence.View, f *evidence.Fingerprint) { v.Manifest.ExpiresAt = time.Now().Add(-time.Second) }, "unavailable", "expired"},
		{"partial_tail", func(v *evidence.View, f *evidence.Fingerprint) { v.Incomplete = true }, "unavailable", "incomplete_journal"},
		{"redacted", func(v *evidence.View, f *evidence.Fingerprint) {
			for _, r := range v.Records {
				if r.State != nil {
					r.State.Redacted = true
				}
			}
		}, "unavailable", "capture_not_exact"},
		{"dropped", func(v *evidence.View, f *evidence.Fingerprint) {
			for _, r := range v.Records {
				if r.State != nil {
					r.State.DroppedRecords++
				}
			}
		}, "unavailable", "capture_not_exact"},
		{"truncated", func(v *evidence.View, f *evidence.Fingerprint) {
			for _, r := range v.Records {
				if r.State != nil {
					r.State.Truncated = true
				}
			}
		}, "unavailable", "capture_not_exact"},
		{"io_failed", func(v *evidence.View, f *evidence.Fingerprint) {
			for _, r := range v.Records {
				if r.State != nil {
					r.State.IOFailed = true
				}
			}
		}, "unavailable", "capture_not_exact"},
		{"offset", func(v *evidence.View, f *evidence.Fingerprint) {
			for _, r := range v.Records {
				if r.Chunk != nil {
					r.Chunk.Offset++
					break
				}
			}
		}, "unavailable", "invalid_offset"},
		{"missing_end", func(v *evidence.View, f *evidence.Fingerprint) {
			for i := range v.Records {
				v.Records[i].ModelEnd = nil
			}
		}, "unavailable", "missing_model_end_or_content"},
		{"missing_spec", func(v *evidence.View, f *evidence.Fingerprint) {
			for i := range v.Records {
				v.Records[i].Spec = nil
			}
		}, "unavailable", "missing_spec_or_summary"},
		{"missing_digest", func(v *evidence.View, f *evidence.Fingerprint) {
			for i := range v.Records {
				v.Records[i].Processing = nil
			}
		}, "unavailable", "processing_digest_missing"},
		{"changed_digest", func(v *evidence.View, f *evidence.Fingerprint) {
			for _, r := range v.Records {
				if r.Processing != nil {
					r.Processing.SHA256 = evidence.Digest([]byte("changed"))
				}
			}
		}, "differs", "processing_digest_differs"},
		{"new_prompt", func(v *evidence.View, f *evidence.Fingerprint) {
			for _, r := range v.Records {
				if r.Spec != nil {
					r.Spec.PromptVersion = "different"
				}
			}
		}, "unavailable", "prompt_version_mismatch"},
		{"changed_failure", func(v *evidence.View, f *evidence.Fingerprint) {
			for _, r := range v.Records {
				if r.Summary != nil {
					r.Summary.FirstFailure = &gt.StageFact{Stage: gt.ContentValidate.String(), State: gt.Failed, Detail: gt.Why("passage_too_short")}
				}
			}
		}, "differs", "failure_boundary_differs"},
		{"transport", func(v *evidence.View, f *evidence.Fingerprint) {
			for _, r := range v.Records {
				if r.Summary != nil {
					r.Summary.FirstFailure = &gt.StageFact{Stage: gt.ProviderStream.String(), State: gt.Failed, Detail: gt.Why("sse_read_failed")}
				}
			}
		}, "unavailable", "failure_outside_model_pipeline"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			v, f := cloneView(t, base), fp
			tc.mutate(&v, &f)
			report := ReplayEvidence(context.Background(), v, f, ReplayStream, validator)
			if report.Status != tc.status || report.Reason != tc.reason {
				t.Fatalf("false replay claim: %+v", report)
			}
		})
	}
}
func TestOBS042BReplayRejectsActualRedactionAndCancellation(t *testing.T) {
	spec, candidate := p0Candidate()
	candidate.Targets[0].EntryMeaning = "Bearer TEST_PRIVATE_TOKEN"
	view, fp := captureFixture(t, spec, p0JSON(candidate), "synthetic-key")
	report := ReplayEvidence(context.Background(), view, fp, ReplayStream, testValidator(t))
	if report.Status != "unavailable" || report.Reason != "capture_not_exact" {
		t.Fatalf("redacted replay: %+v", report)
	}
	spec, candidate = p0Candidate()
	view, fp = captureFixture(t, spec, p0JSON(candidate), "synthetic-key")
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	report = ReplayEvidence(ctx, view, fp, ReplayStream, testValidator(t))
	if report.Status != "unavailable" || report.Reason != "replay_cancelled" {
		t.Fatalf("cancelled: %+v", report)
	}
	report = ReplayEvidence(context.Background(), view, fp, ReplayMode("unknown"), testValidator(t))
	if report.Reason != "invalid_mode" {
		t.Fatal(report)
	}
}

package ai

import (
	"context"
	"io"
	"strings"
	"testing"
)

// Keep root ordering explicit: passage is a stream-owned first field.
func boundaryDocument(keys, values []string) string {
	parts := make([]string, len(keys))
	for i, key := range keys {
		parts[i] = p0JSON(key) + ":" + values[i]
	}
	return "{" + strings.Join(parts, ",") + "}"
}

func TestBoundarySchemaEveryField(t *testing.T) {
	_, candidate := p0Candidate()
	rootKeys := []string{"passage", "tags", "targets"}
	rootValues := []string{p0JSON(candidate.Passage), p0JSON(candidate.Tags), p0JSON(candidate.Targets)}
	targetKeys := []string{"source_entry", "entry_meaning", "hint_phrase"}
	targetValues := []string{p0JSON(candidate.Targets[0].SourceEntry), p0JSON(candidate.Targets[0].EntryMeaning), p0JSON(candidate.Targets[0].HintPhrase)}
	check := func(t *testing.T, raw, reason string) {
		t.Helper()
		var got Candidate
		err := decodeCandidateStrict([]byte(raw), &got)
		d := DescribeFailure(err)
		if err == nil || d.Stage != "candidate_schema" || d.Reason != reason {
			t.Fatalf("want %s; got %+v", reason, d)
		}
	}
	var valid Candidate
	if err := decodeCandidateStrict([]byte(boundaryDocument(rootKeys, rootValues)), &valid); err != nil {
		t.Fatal(err)
	}
	for _, level := range []string{"root", "target"} {
		keys, values := rootKeys, rootValues
		if level == "target" {
			keys, values = targetKeys, targetValues
		}
		for index, key := range keys {
			for _, mutation := range []string{"missing", "duplicate", "alias", "null", "type"} {
				t.Run(level+"/"+key+"/"+mutation, func(t *testing.T) {
					kk, vv := append([]string(nil), keys...), append([]string(nil), values...)
					reason := "candidate_keys_invalid"
					if level == "target" {
						reason = "target_keys_invalid"
					}
					switch mutation {
					case "missing":
						kk = append(kk[:index], kk[index+1:]...)
						vv = append(vv[:index], vv[index+1:]...)
					case "duplicate":
						kk = append(kk, key)
						vv = append(vv, values[index])
						reason = "json_duplicate_key"
					case "alias":
						kk[index] = strings.ToUpper(key)
					case "null":
						vv[index] = "null"
						reason = "json_null"
					case "type":
						vv[index] = "false"
						reason = "json_invalid"
						if key == "targets" {
							reason = "targets_type_invalid"
						}
					}
					if level == "root" && key == "passage" && mutation != "duplicate" {
						reason = "passage_not_first"
					}
					raw := boundaryDocument(kk, vv)
					if level == "target" {
						rv := append([]string(nil), rootValues...)
						rv[2] = "[" + raw + "," + p0JSON(candidate.Targets[1]) + "]"
						raw = boundaryDocument(rootKeys, rv)
					}
					check(t, raw, reason)
				})
			}
		}
	}
}

func TestBoundarySSEFraming(t *testing.T) {
	_, candidate := p0Candidate()
	wire := p0SSE(p0JSON(candidate))
	for _, prefix := range []string{"data:\n\n", ": ping\r\n\r\n", "event: message\nid: 1\nretry: 1000\n\n"} {
		for _, crlf := range []bool{false, true} {
			body := prefix + wire
			if crlf {
				body = strings.ReplaceAll(body, "\n", "\r\n")
			}
			stream := openRouterStream{io.NopCloser(strings.NewReader(body))}
			var clean strings.Builder
			got, err := stream.Receive(context.Background(), func(s string) error { clean.WriteString(s); return nil })
			if err != nil || got.Passage != candidate.Passage || clean.String() != "Young people share grapes and another grape." {
				t.Fatalf("valid SSE framing: %v", err)
			}
		}
	}
}

func TestBoundarySSEInvalidUTF8RejectedBeforeReplacement(t *testing.T) {
	_, candidate := p0Candidate()
	wire := strings.Replace(p0SSE(p0JSON(candidate)), "people", "pe"+string([]byte{0xff})+"ple", 1)
	stream := openRouterStream{io.NopCloser(strings.NewReader(wire))}
	var preview strings.Builder
	_, err := stream.Receive(context.Background(), func(s string) error { preview.WriteString(s); return nil })
	if DescribeFailure(err).Reason != "sse_event_encoding_invalid" || preview.Len() != 0 {
		t.Fatalf("invalid wire encoding was silently replaced: %+v; emitted=%d", DescribeFailure(err), preview.Len())
	}
}

func TestBoundaryMultipleCompleteChoicesAreNotMergedAsValid(t *testing.T) {
	_, candidate := p0Candidate()
	choice := map[string]any{"delta": map[string]string{"content": p0JSON(candidate)}}
	wire := "data: " + p0JSON(map[string]any{"choices": []any{choice, choice}}) + "\n\n"
	stream := openRouterStream{io.NopCloser(strings.NewReader(wire))}
	_, err := stream.Receive(context.Background(), func(string) error { return nil })
	if DescribeFailure(err).Reason != "json_trailing_content" {
		t.Fatalf("two complete choices accepted as one result: %v", err)
	}
}

func TestBoundaryMinimumWordThreshold(t *testing.T) {
	validator := testValidator(t)
	for _, minimum := range []int{6, 7, 8} {
		spec, candidate := p0Candidate() // independently counted: seven clean words
		spec.MinimumWords = minimum
		batch, err := validator.Validate(context.Background(), spec, candidate)
		if minimum <= 7 {
			if err != nil || batch.WordCount != 7 {
				t.Fatalf("legal boundary: %v", err)
			}
		} else {
			detail := DescribeFailure(err)
			if detail.Reason != "passage_too_short" || detail.Actual != 7 || detail.Limit != 8 {
				t.Fatal("wrong word-count boundary")
			}
		}
	}
}

package ai

import (
	"encoding/json"
	"errors"
	"slices"
	"strings"
	"unicode/utf8"
)

var errSnapshot = errors.New("invalid current validated snapshot")

// DecodeSnapshot accepts only the current persisted shape. It verifies stored
// structure and spans, never reselects a meaning or reruns lexical validation.
func DecodeSnapshot(raw []byte) (ValidatedBatch, error) {
	var batch ValidatedBatch
	if !utf8.Valid(raw) || rejectDuplicateJSONKeys(raw) != nil {
		return batch, errSnapshot
	}
	var object map[string]json.RawMessage
	if json.Unmarshal(raw, &object) != nil || !exactObjectKeys(object, []string{"passage", "tags", "targets", "word_count", "validator_version"}) {
		return batch, errSnapshot
	}
	var targets []map[string]json.RawMessage
	if json.Unmarshal(object["targets"], &targets) != nil {
		return batch, errSnapshot
	}
	for _, target := range targets {
		if !exactObjectKeys(target, []string{"entry", "entry_meaning", "hint_phrase", "hint_occurrences", "passage_occurrences"}) {
			return batch, errSnapshot
		}
		for _, field := range []string{"hint_occurrences", "passage_occurrences"} {
			var spans []map[string]json.RawMessage
			if json.Unmarshal(target[field], &spans) != nil || len(spans) == 0 {
				return batch, errSnapshot
			}
			for _, span := range spans {
				if !exactObjectKeys(span, []string{"surface", "start", "end"}) ||
					string(span["start"]) == "null" || string(span["end"]) == "null" {
					return batch, errSnapshot
				}
			}
		}
	}
	if json.Unmarshal(raw, &batch) != nil || ValidateSnapshot(batch) != nil {
		return ValidatedBatch{}, errSnapshot
	}
	return batch, nil
}

func validEntryMeaning(value string) bool {
	return utf8.ValidString(value) && value != "" && strings.TrimSpace(value) == value && utf8.RuneCountInString(value) <= 500
}

// ValidateSnapshot is shared by the writer and reader. Semantic/language and
// lexical decisions belong exclusively to the initial candidate validator.
func ValidateSnapshot(batch ValidatedBatch) error {
	if batch.Passage == "" || !utf8.ValidString(batch.Passage) || batch.WordCount < 1 ||
		batch.ValidatorVersion == "" || len(batch.Targets) == 0 || len(batch.Tags) < 1 || len(batch.Tags) > 3 {
		return errSnapshot
	}
	for _, tag := range batch.Tags {
		if tag == "" || strings.TrimSpace(tag) != tag || utf8.RuneCountInString(tag) > 100 {
			return errSnapshot
		}
	}
	entries := make(map[string]bool, len(batch.Targets))
	var all []Occurrence
	for _, target := range batch.Targets {
		if target.Entry == "" || strings.TrimSpace(target.Entry) != target.Entry || entries[target.Entry] ||
			!validEntryMeaning(target.EntryMeaning) || target.HintPhrase == "" ||
			!validStoredSpans(target.HintPhrase, target.HintOccurrences) ||
			!validStoredSpans(batch.Passage, target.PassageOccurrences) {
			return errSnapshot
		}
		entries[target.Entry] = true
		all = append(all, target.PassageOccurrences...)
	}
	slices.SortFunc(all, func(a, b Occurrence) int { return a.Start - b.Start })
	if !validStoredSpans(batch.Passage, all) {
		return errSnapshot
	}
	return nil
}

func validStoredSpans(text string, spans []Occurrence) bool {
	if len(spans) == 0 || !utf8.ValidString(text) {
		return false
	}
	runes, previous := []rune(text), 0
	for _, span := range spans {
		if span.Start < previous || span.End <= span.Start || span.End > len(runes) ||
			string(runes[span.Start:span.End]) != span.Surface {
			return false
		}
		previous = span.End
	}
	return true
}

package ai

import (
	"context"
	"encoding/json"
	"errors"
	"reflect"
	"strings"

	"wordweave/internal/generationtrace"
)

func traceResult(ctx context.Context, stage generationtrace.Stage, err error) {
	state := generationtrace.OK
	d := generationtrace.Why("")
	if err != nil {
		state = generationtrace.Failed
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			state = generationtrace.Cancelled
		}
		detail := DescribeFailure(err)
		d.Reason, d.Field, d.Target, d.Actual, d.Limit = detail.Reason, detail.Field, detail.Target, detail.Actual, detail.Limit
		var syntax *json.SyntaxError
		if errors.As(err, &syntax) {
			d.Start, d.End = syntax.Offset-1, syntax.Offset
		}
		var typeErr *json.UnmarshalTypeError
		if errors.As(err, &typeErr) {
			d.Start, d.End = typeErr.Offset-1, typeErr.Offset
			switch typeErr.Type.Kind() {
			case reflect.String:
				d.ExpectedType = "string"
			case reflect.Slice, reflect.Array:
				d.ExpectedType = "array"
			case reflect.Map, reflect.Struct:
				d.ExpectedType = "object"
			case reflect.Bool:
				d.ExpectedType = "boolean"
			}
			for _, kind := range []string{"string", "number", "bool", "array", "object", "null"} {
				if typeErr.Value == kind || strings.HasPrefix(typeErr.Value, kind+" ") {
					d.ActualType = kind
					if kind == "bool" {
						d.ActualType = "boolean"
					}
					break
				}
			}
		}
	}
	generationtrace.From(ctx).End(stage, state, d)
}

// Observe just the permitted envelope fields. In particular error.message,
// metadata, reasoning and arbitrary headers never enter the trace. This decoder
// does not decide whether the business receiver accepts the frame.
func observeProviderEnvelope(ctx context.Context, data string, frame int64, apiKey string) {
	trace := generationtrace.From(ctx)
	if trace == nil {
		return
	}
	base := generationtrace.ProviderFact{Frame: frame, Bytes: int64(len(data)), SyntaxOffset: -1}
	var envelope struct {
		ID      string `json:"id"`
		Choices []struct {
			Index        *int    `json:"index"`
			FinishReason *string `json:"finish_reason"`
		} `json:"choices"`
		Usage *struct {
			Prompt     int64 `json:"prompt_tokens"`
			Completion int64 `json:"completion_tokens"`
			Total      int64 `json:"total_tokens"`
		} `json:"usage"`
		Error json.RawMessage `json:"error"`
	}
	if err := json.Unmarshal([]byte(data), &envelope); err != nil {
		var syntax *json.SyntaxError
		if errors.As(err, &syntax) {
			base.SyntaxOffset = syntax.Offset
		}
		trace.Provider(generationtrace.ProviderStream, base)
		return
	}
	base.ID = privateSafeID(envelope.ID, apiKey)
	if envelope.Usage != nil {
		base.UsageProvided = true
		base.PromptTokens, base.CompletionTokens, base.TotalTokens = envelope.Usage.Prompt, envelope.Usage.Completion, envelope.Usage.Total
	}
	if len(envelope.Error) > 0 && string(envelope.Error) != "null" {
		base.ErrorPresent = true
		var upstreamError struct {
			Code json.RawMessage `json:"code"`
		}
		if json.Unmarshal(envelope.Error, &upstreamError) != nil {
			base.ErrorCodeType = "other"
		} else if len(upstreamError.Code) == 0 {
			base.ErrorCodeType = "not_provided"
		} else if string(upstreamError.Code) == "null" {
			base.ErrorCodeType = "null"
		} else if upstreamError.Code[0] == '"' {
			base.ErrorCodeType = "string"
		} else if json.Unmarshal(upstreamError.Code, &base.ErrorCode) == nil {
			base.ErrorCodeType = "number"
		} else {
			base.ErrorCodeType = "other"
		}
	}
	if len(envelope.Choices) == 0 {
		trace.Provider(generationtrace.ProviderStream, base)
	}
	for _, choice := range envelope.Choices {
		fact := base
		if choice.Index != nil {
			fact.Choice, fact.ChoiceProvided = *choice.Index, true
		}
		if choice.FinishReason != nil {
			fact.FinishReason = *choice.FinishReason
		}
		trace.Provider(generationtrace.ProviderStream, fact)
	}
}

