)

func testValidator(t testing.TB) Validator {
	t.Helper()
	lexicon, err := LoadEmbeddedLexicon()
	if err != nil {
		t.Fatal(err)
	}
	return NewValidator(lexicon)
}

func TestValidatorBuildsRuneOffsetsAndAllowsInflection(t *testing.T) {
	t.Parallel()
	passage := strings.TrimSpace("Café learners are learning together. " + strings.Repeat("They discuss useful examples in a friendly study group. ", 7))
	spec := GenerationSpec{MeaningLanguage: "zh", MinimumWords: 50, Entries: []string{"learn"}}
	candidate := Candidate{
		Passage: annotateFixture(passage, "learn", []string{"learning"}), Tags: []string{"学习"},
		Targets: []CandidateTarget{{
			SourceEntry: "learn", EntryMeaning: "学习", HintPhrase: "learning(learn) together while we learn through learning",
		}},
	}
	batch, err := testValidator(t).Validate(context.Background(), spec, candidate)
	if err != nil {
		t.Fatal(err)
	}
	// v3 also recognizes the omitted direct derivation learners.
	if len(batch.Targets) != 1 || len(batch.Targets[0].PassageOccurrences) != 2 {
		t.Fatalf("unexpected targets: %#v", batch.Targets)
	}
	if len(batch.Targets[0].HintOccurrences) != 3 {
		t.Fatalf("hint occurrences = %#v, want three blanks", batch.Targets[0].HintOccurrences)
	}
	if batch.Targets[0].HintOccurrences[0].Surface != "learning" || batch.Targets[0].HintOccurrences[1].Surface != "learn" || batch.Targets[0].HintOccurrences[2].Surface != "learning" {
		t.Fatalf("unexpected hint occurrences: %#v", batch.Targets[0].HintOccurrences)
	}
	occurrence := batch.Targets[0].PassageOccurrences[1]
	if occurrence.Surface != "learning" {
		t.Fatalf("unexpected occurrence: %#v", occurrence)
	}
}

func TestValidatorRejectsMissingTargetAndWrongMeaningLanguage(t *testing.T) {
	t.Parallel()
	spec := GenerationSpec{MeaningLanguage: "ja", MinimumWords: 1, Entries: []string{"learn"}}
	candidate := Candidate{
		Passage: "People study together.", Tags: []string{"study"},
		Targets: []CandidateTarget{{SourceEntry: "learn", EntryMeaning: "study", HintPhrase: "learn together"}},
	}
	if _, err := testValidator(t).Validate(context.Background(), spec, candidate); err == nil {
		t.Fatal("candidate with wrong language and missing passage target unexpectedly passed")
	}
}

func TestCountWordsHandlesJoiners(t *testing.T) {
	t.Parallel()
	if got := CountWords("well-known learners don't stop"); got != 4 {
		t.Fatalf("CountWords = %d, want 4", got)
	}
}

func TestAllowedFormsIncludesCommonIrregularsWithoutInventedPastForms(t *testing.T) {
	t.Parallel()
	var forms []string
	for form := range testValidator(t).lexicon.knownForms("run") {
		forms = append(forms, form)
	}
	if !containsFold(forms, "ran") || !containsFold(forms, "running") {
		t.Fatalf("run forms missing common inflection: %v", forms)
	}
	if containsFold(forms, "runed") || containsFold(forms, "runing") {
		t.Fatalf("run forms contain invented inflection: %v", forms)
	}
}

func TestJapaneseMeaningMayUseKanjiOnly(t *testing.T) {
	t.Parallel()
	if !matchesMeaningLanguage("学習", "ja") {
		t.Fatal("valid kanji-only Japanese label was rejected")
	}
}

package observability

import (
	"fmt"
	"log/slog"
	"net/http"
	"sort"
	"strconv"
	"sync"

	"wordweave/internal/generationtrace"
)

type generationKey struct{ name, stage, result string }
type generationMetrics struct {
	mu       sync.Mutex
	inflight int64
	values   map[generationKey]float64
}

func (m *Metrics) GenerationTrace(requestID string) *generationtrace.Trace {
	g := &m.generation
	g.mu.Lock()
	if g.values == nil {
		g.values = make(map[generationKey]float64)
	}
	g.inflight++
	g.values[generationKey{name: "requests_total"}]++
	g.mu.Unlock()
	return generationtrace.New(requestID, g)
}
func (g *generationMetrics) Event(e generationtrace.Event) {
	g.mu.Lock()
	add := func(name, stage, result string, value float64) { g.values[generationKey{name, stage, result}] += value }
	switch e.Kind {
	case "stage_end":
		add("stage_total", e.Fact.Stage, string(e.Fact.State), 1)
		add("stage_duration_seconds_sum", e.Fact.Stage, string(e.Fact.State), float64(e.Fact.DurationMS)/1000)
		if e.Fact.State == generationtrace.Failed || e.Fact.State == generationtrace.Cancelled {
			add("failure_total", e.Fact.Stage, e.Fact.Detail.Reason, 1)
		}
	case "outcome_confirmed":
		add("confirmed_outcomes_total", "", e.Outcome, 1)
		if e.Refunded {
			add("confirmed_refunds_total", "", "", 1)
		}
	case "settlement":
		add("settlement_attempts_total", "", e.Outcome, 1)
		if e.Late && e.Outcome != "pending" && e.Outcome != "unknown" {
			add("late_settlement_attempts_total", "", e.Outcome, 1)
		}
	case "settlement_recovered":
		add("settlements_recovered_total", "", e.Outcome, 1)
	case "first_provider_content", "first_browser_content":
		add(e.Kind+"_seconds_sum", "", "", float64(e.ElapsedMS)/1000)
		add(e.Kind+"_total", "", "", 1)
	case "fact":
		if e.Fact.Stage == "provider_stream" && e.Fact.Check == "termination" {
			add("provider_terminations_total", "", e.Fact.Detail.Reason, 1)
		}
		if e.Fact.Stage == "delivery" && e.Fact.Detail.Reason != "" {
			add("delivery_failures_total", "", e.Fact.Detail.Reason, 1)
		}
	}
	g.mu.Unlock()
	// Only Trace-sanitized values; never an error string or arbitrary payload.
	slog.Info("generation_trace", "event", e)
}
func (g *generationMetrics) Summary(s generationtrace.Summary) {
	g.mu.Lock()
	g.inflight--
	g.values[generationKey{name: "request_duration_seconds_sum"}] += float64(s.ElapsedMS) / 1000
	g.mu.Unlock()
	slog.Info("generation_summary", "summary", s)
}
func (m *Metrics) writeGeneration(w http.ResponseWriter) {
	g := &m.generation
	g.mu.Lock()
	values := make(map[generationKey]float64, len(g.values))
	keys := make([]generationKey, 0, len(g.values))
	for k, v := range g.values {
		values[k] = v
		keys = append(keys, k)
	}
	active := g.inflight
	g.mu.Unlock()
	sort.Slice(keys, func(i, j int) bool {
		a, b := keys[i], keys[j]
		if a.name != b.name {
			return a.name < b.name
		}
		if a.stage != b.stage {
			return a.stage < b.stage
		}
		return a.result < b.result
	})
	fmt.Fprintln(w, "# TYPE wordweave_generation_in_flight gauge")
	fmt.Fprintf(w, "wordweave_generation_in_flight %d\n", active)
	last := ""
	for _, k := range keys {
		if k.name != last {
			fmt.Fprintf(w, "# TYPE wordweave_generation_%s counter\n", k.name)
			last = k.name
		}
		fmt.Fprintf(w, "wordweave_generation_%s{stage=%s,result=%s} %g\n", k.name, strconv.Quote(k.stage), strconv.Quote(k.result), values[k])
	}
}

