package observability

import (
	"fmt"
	"net/http"
	"sort"
	"strconv"
	"sync"
	"sync/atomic"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

type httpKey struct {
	method string
	route  string
	status int
}

type httpValue struct {
	count       uint64
	durationSum float64
}

type Metrics struct {
	generation generationMetrics
	inFlight   atomic.Int64
	mutex      sync.Mutex
	http       map[httpKey]httpValue
}

func NewMetrics() *Metrics { return &Metrics{http: make(map[httpKey]httpValue)} }

func (metrics *Metrics) Begin() func(method, route string, status int) {
	metrics.inFlight.Add(1)
	started := time.Now()
	return func(method, route string, status int) {
		metrics.inFlight.Add(-1)
		if route == "" {
			route = "unmatched"
		}
		key := httpKey{method: method, route: route, status: status}
		metrics.mutex.Lock()
		value := metrics.http[key]
		value.count++
		value.durationSum += time.Since(started).Seconds()
		metrics.http[key] = value
		metrics.mutex.Unlock()
	}
}

func (metrics *Metrics) Handler(pool *pgxpool.Pool) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, _ *http.Request) {
		writer.Header().Set("Content-Type", "text/plain; version=0.0.4; charset=utf-8")
		writer.Header().Set("Cache-Control", "no-store")
		_, _ = fmt.Fprintln(writer, "# HELP wordweave_up Whether the process is serving metrics.")
		_, _ = fmt.Fprintln(writer, "# TYPE wordweave_up gauge")
		_, _ = fmt.Fprintln(writer, "wordweave_up 1")
		_, _ = fmt.Fprintln(writer, "# TYPE wordweave_http_requests_in_flight gauge")
		_, _ = fmt.Fprintf(writer, "wordweave_http_requests_in_flight %d\n", metrics.inFlight.Load())
		metrics.writeHTTP(writer)
		metrics.writeGeneration(writer)
		stats := pool.Stat()
		_, _ = fmt.Fprintln(writer, "# TYPE wordweave_db_pool_connections gauge")
		_, _ = fmt.Fprintf(writer, "wordweave_db_pool_connections{state=\"acquired\"} %d\n", stats.AcquiredConns())
		_, _ = fmt.Fprintf(writer, "wordweave_db_pool_connections{state=\"idle\"} %d\n", stats.IdleConns())
		_, _ = fmt.Fprintf(writer, "wordweave_db_pool_connections{state=\"total\"} %d\n", stats.TotalConns())
		_, _ = fmt.Fprintln(writer, "# TYPE wordweave_db_pool_acquire_total counter")
		_, _ = fmt.Fprintf(writer, "wordweave_db_pool_acquire_total %d\n", stats.AcquireCount())
		_, _ = fmt.Fprintln(writer, "# TYPE wordweave_db_pool_acquire_duration_seconds counter")
		_, _ = fmt.Fprintf(writer, "wordweave_db_pool_acquire_duration_seconds %g\n", stats.AcquireDuration().Seconds())
	})
}

func (metrics *Metrics) writeHTTP(writer http.ResponseWriter) {
	metrics.mutex.Lock()
	keys := make([]httpKey, 0, len(metrics.http))
	values := make(map[httpKey]httpValue, len(metrics.http))
	for key, value := range metrics.http {
		keys = append(keys, key)
		values[key] = value
	}
	metrics.mutex.Unlock()
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].route != keys[j].route {
			return keys[i].route < keys[j].route
		}
		if keys[i].method != keys[j].method {
			return keys[i].method < keys[j].method
		}
		return keys[i].status < keys[j].status
	})
	_, _ = fmt.Fprintln(writer, "# TYPE wordweave_http_requests_total counter")
	_, _ = fmt.Fprintln(writer, "# TYPE wordweave_http_request_duration_seconds counter")
	for _, key := range keys {
		labels := "method=" + strconv.Quote(key.method) + ",route=" + strconv.Quote(key.route) + ",status=" + strconv.Quote(strconv.Itoa(key.status))
		_, _ = fmt.Fprintf(writer, "wordweave_http_requests_total{%s} %d\n", labels, values[key].count)
		_, _ = fmt.Fprintf(writer, "wordweave_http_request_duration_seconds{%s} %g\n", labels, values[key].durationSum)
	}
}

package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"wordweave/internal/ai"
	"wordweave/internal/httpapi"
	"wordweave/internal/maintenance"
	"wordweave/internal/observability"
	"wordweave/internal/platform/config"
	"wordweave/internal/platform/postgres"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	if err := run(ctx); err != nil && !errors.Is(err, context.Canceled) {
		slog.Error("server stopped", "error", err)
		os.Exit(1)
	}
}

func run(ctx context.Context) error {
	cfg, err := config.Load()
	if err != nil {
		return err
	}
	observability.ConfigureLogging(cfg.LogLevel)
	// Fail before startup recovery can mutate database state. httpapi.New
	// obtains the same immutable instance through the once-only loader.
	if _, err := ai.LoadEmbeddedLexicon(); err != nil {
		return err
	}
	pool, err := postgres.Open(ctx, cfg.AppDatabaseURL, "wordweave", cfg.AppDBMaxConns)
	if err != nil {
		return err
	}
	defer pool.Close()
	aiPool, err := postgres.Open(ctx, cfg.AIDatabaseURL, "wordweave-ai", cfg.AIDBMaxConns)
	if err != nil {
		return err
	}
	defer aiPool.Close()
	if err := postgres.Verify(ctx, pool); err != nil {
		return err
	}
	settled, err := maintenance.SettleActiveGenerations(ctx, pool, "startup_recovery")
	if err != nil {
		return err
	}
	if settled > 0 {
		slog.Warn("settled orphaned generations", "count", settled)
	}

	apiServer, err := httpapi.New(cfg, pool, aiPool)
	if err != nil {
		return err
	}
	go apiServer.RunMaintenance(ctx)

	server := &http.Server{
		Addr:              cfg.HTTPAddr,
		Handler:           apiServer.Handler(),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	metricsServer := &http.Server{
		Addr: cfg.MetricsAddr, Handler: apiServer.MetricsHandler(),
		ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 10 * time.Second,
		WriteTimeout: 10 * time.Second, IdleTimeout: 30 * time.Second,
	}
	errCh := make(chan error, 2)
	go func() {
		errCh <- normalizeServerError(server.ListenAndServe())
	}()
	go func() {
		errCh <- normalizeServerError(metricsServer.ListenAndServe())
	}()
	apiServer.SetReady(true)

	select {
	case <-ctx.Done():
		apiServer.SetReady(false)
		shutdownCtx, cancel := context.WithTimeout(context.Background(), cfg.ShutdownTimeout)
		shutdownErr := server.Shutdown(shutdownCtx)
		cancel()
		settleCtx, settleCancel := context.WithTimeout(context.Background(), 5*time.Second)
		settleErr := apiServer.Stop(settleCtx)
		settleCancel()
		if shutdownErr != nil {
			_ = server.Close()
		}
		metricsCtx, metricsCancel := context.WithTimeout(context.Background(), 5*time.Second)
		metricsErr := metricsServer.Shutdown(metricsCtx)
		metricsCancel()
		return errors.Join(shutdownErr, settleErr, metricsErr)
	case err := <-errCh:
		apiServer.SetReady(false)
		stopCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		stopErr := apiServer.Stop(stopCtx)
		cancel()
		_ = server.Close()
		_ = metricsServer.Close()
		return errors.Join(err, stopErr)
	}
}

func normalizeServerError(err error) error {
	if errors.Is(err, http.ErrServerClosed) {
		return nil
	}
	return err
}

package main

import (
	"context"
	"errors"
	"flag"
	"io"
	"log/slog"
	"time"

	"wordweave/internal/platform/postgres"
)

func runEntryMeaningCutover(ctx context.Context, args []string, maintenanceURL string) error {
	options, err := parseEntryMeaningCutoverOptions(args)
	if err != nil {
		return err
	}
	if maintenanceURL == "" {
		return errors.New("MAINTENANCE_DATABASE_URL is required; no application-credential fallback")
	}
	// Deliberately does not load app configuration, decrypt model credentials,
	// initialize a provider, start HTTP, or run background maintenance.
	pool, err := postgres.Open(ctx, maintenanceURL, "wordweave-entry-meaning-cutover", 1)
	if err != nil {
		return errors.New("cannot open explicit maintenance connection")
	}
	defer pool.Close()
	result, err := postgres.CutoverEntryMeaning(ctx, pool, options)
	if err != nil {
		return err // CutoverError exposes stage/outcome only, never database detail.
	}
	slog.Info("entry-meaning cutover finished", "outcome", result.Outcome, "deleted_counts", result.Deleted)
	return nil
}

func parseEntryMeaningCutoverOptions(args []string) (postgres.CutoverOptions, error) {
	var options postgres.CutoverOptions
	flags := flag.NewFlagSet("cutover-entry-meaning", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	flags.StringVar(&options.ExpectedDatabase, "database", "", "verified exact database name")
	flags.StringVar(&options.ExpectedSystemID, "system-id", "", "verified PostgreSQL cluster system identifier")
	flags.StringVar(&options.ExpectedRole, "role", "", "verified controlled maintenance role")
	flags.BoolVar(&options.WritersStopped, "writers-stopped", false, "all application writers have been stopped")
	flags.DurationVar(&options.LockTimeout, "lock-timeout", 0, "rehearsed lock timeout")
	flags.DurationVar(&options.StatementTimeout, "statement-timeout", 0, "rehearsed statement timeout")
	if flags.Parse(args) != nil || flags.NArg() != 0 ||
		options.ExpectedDatabase == "" || options.ExpectedSystemID == "" || options.ExpectedRole == "" ||
		!options.WritersStopped || options.LockTimeout < time.Millisecond || options.StatementTimeout < time.Millisecond {
		return options, errors.New("cutover requires --database, --system-id, --role, --writers-stopped, --lock-timeout and --statement-timeout; no bypass or retry options")
	}
	return options, nil
}

package main

import (
	"context"
	"testing"
)

func TestCutoverRequiresExplicitTargetAndStoppedWriters(t *testing.T) {
	valid := []string{"--database", "synthetic", "--system-id", "1234", "--role", "postgres", "--writers-stopped", "--lock-timeout", "1s", "--statement-timeout", "10s"}
	if _, err := parseEntryMeaningCutoverOptions(valid); err != nil {
		t.Fatal(err)
	}
	for _, args := range [][]string{nil, valid[:6], append(append([]string{}, valid...), "--force"), append(append([]string{}, valid...), "--lock-timeout", "0")} {
		if _, err := parseEntryMeaningCutoverOptions(args); err == nil {
			t.Fatal("unsafe options accepted")
		}
	}
	if err := runEntryMeaningCutover(context.Background(), valid, ""); err == nil {
		t.Fatal("application credential fallback must not exist")
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"strings"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"wordweave/internal/observability"
	"wordweave/internal/platform/config"
	"wordweave/internal/platform/postgres"
	"wordweave/internal/platform/security"
)

func main() {
	if err := run(context.Background(), os.Args[1:]); err != nil {
		slog.Error("administrative command failed", "error", err)
		os.Exit(1)
	}
}

func run(ctx context.Context, args []string) error {
	if len(args) > 0 && args[0] == "cutover-entry-meaning" {
		return runEntryMeaningCutover(ctx, args[1:], os.Getenv("MAINTENANCE_DATABASE_URL"))
	}
	if len(args) != 1 {
		return errors.New("usage: wordweave-admin migrate|verify|create-admin|cutover-entry-meaning [options]")
	}
	cfg, err := config.Load()
	if err != nil {
		return fmt.Errorf("load configuration: %w", err)
	}
	observability.ConfigureLogging(cfg.LogLevel)
	pool, err := postgres.Open(ctx, cfg.AppDatabaseURL, "wordweave-admin", 2)
	if err != nil {
		return err
	}
	defer pool.Close()

	switch args[0] {
	case "migrate":
		return postgres.Migrate(ctx, pool)
	case "verify":
		return postgres.Verify(ctx, pool)
	case "create-admin":
		return createAdmin(ctx, pool, os.Getenv("ADMIN_USERNAME"), os.Getenv("ADMIN_PASSWORD"))
	default:
		return errors.New("usage: wordweave-admin migrate|verify|create-admin")
	}
}

func createAdmin(ctx context.Context, pool *pgxpool.Pool, username, password string) error {
	if !validUsername(username) {
		return errors.New("ADMIN_USERNAME must be 3-32 ASCII letters, digits, or underscores")
	}
	if err := security.ValidatePassword(password); err != nil {
		return fmt.Errorf("ADMIN_PASSWORD: %w", err)
	}
	hash, err := security.HashPassword(password)
	if err != nil {
		return fmt.Errorf("hash administrator password: %w", err)
	}
	commandCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	if _, err := pool.Exec(commandCtx, `
		INSERT INTO wordweave.accounts(username, password_hash, role, group_code, status, ui_locale)
		VALUES ($1, $2, 'admin', NULL, 'active', NULL)`, username, hash); err != nil {
		return fmt.Errorf("create administrator: %w", err)
	}
	return nil
}

func validUsername(username string) bool {
	if len(username) < 3 || len(username) > 32 || strings.TrimSpace(username) != username {
		return false
	}
	for _, char := range username {
		if !((char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || (char >= '0' && char <= '9') || char == '_') {
			return false
		}
	}
	return true
}
